// مولّدة آلياً بواسطة scripts/split-fatwas.mjs — لا تُعدَّل يدوياً.
export default [{"id":2,"question":"مجموعة أسئلة يا فضيلة الشيخ تدور حول الأغاني، وبعض الإخوة يقول أنه يعلم أنها مُحرَّمة، وأنه عقد العزم على تركها، ولكن لا يزال بعض بواقيها متعلّقًا بقلبه، ويقول: هل من نصيحةٍ؟","title":"ما النصيحة لمن يستمع الأغاني؟","answer":"الجواب: أما الأغاني: فقد ابتُلي بها الناسُ اليوم، وكثرت بين الناس: في الإذاعات، والتلفاز، وفي الأشرطة، وفي غير ذلك من أنواع التسجيل، ولا شكَّ أنها خطرٌ عظيمٌ، وأنها بلاءٌ كبيرٌ، ومن أسباب وقوع الفواحش، وظُلمة القلوب وحيرتها، وإقبالها على الفواحش، وثُقلها عن الطاعات، فالواجب الحذر منها، وعدم استماعها، فإنها رُقية الزنا، وقُرآن الشيطان، فيجب الحذر من شرِّها.\nقال الله جلَّ وعلا: وَمِنَ النَّاسِ مَنْ يَشْتَرِي لَهْوَ الْحَدِيثِ لِيُضِلَّ عَنْ سَبِيلِ اللَّهِ بِغَيْرِ عِلْمٍ وَيَتَّخِذَهَا هُزُوًا أُولَئِكَ لَهُمْ عَذَابٌ مُهِينٌ ۝ وَإِذَا تُتْلَى عَلَيْهِ آيَاتُنَا وَلَّى مُسْتَكْبِرًا كَأَنْ لَمْ يَسْمَعْهَا كَأَنَّ فِي أُذُنَيْهِ وَقْرًا فَبَشِّرْهُ بِعَذَابٍ أَلِيمٍ [لقمان:6- 7]، قال أكثرُ أهل العلم من المُفسرين وغيرهم: إنَّ لهو الحديث هو الغناء، وأنه يصدُّ عن سبيل الله، ولهذا قال: لِيُضِلَّ عَنْ سَبِيلِ اللَّهِ، قُرئ: لِيُضِلَّ، وقُرئ: لِيَضَلَّ.\nفدلَّت الآيةُ الكريمة على أنَّ الغناء من أسباب الضَّلال عن سبيل الله والإضلال، ومن أسباب اتِّخاذ سبيل الله هزوًا، ومن أسباب الاستكبار عن سماع القرآن، وهذه مصائب كثيرة، ومصائب عظيمة: الضَّلال والإضلال، واتِّخاذ آيات الله هزوًا، والتثاقل والاستكبار عن سماع القرآن، فهذه ثلاث مصائب ذكرها، ثلاث مصائب عظيمة، ثلاث عقوبات، فيجب الحذر من هذا البلاء العظيم.\nوصحَّ عن رسول الله ﷺ أنه قال: ليكوننَّ من أمتي أقوامٌ يستحلُّون الحِرَ والحريرَ والخمرَ والمعازفَ أخرجه البخاري في \"الصحيح\"، وخرجه جماعةٌ آخرون.\nوبيَّن ﷺ أنه يكون في آخر الزمان قومٌ -وقد وقع هذا من أزمان طويلة، وهو من علامات النبوة- يستحلُّون الحِرَ والحريرَ، يستحلون الزنا، وقد وقع ذلك ممن لا يُبالي، فاستحلَّ الزنا والفواحش، ولم يُبالِ.\nوالحرير: لبس الحرير –يعني: للرجال- وهو محرَّم على الرجال.\nوالخمر كذلك قد تساهل الناسُ في شُربه، واستحلَّه منهم مَن شاء الله، فالأمر عظيم.\nثم قال والمعازف، والمعازف يدخل فيها الغناء وآلات اللَّهو، يقال: عزف إذا غنَّى، وإذا ضرب بآلة الطرب، فالعزف هو الغناء، فإذا كان معه الضَّرب بالدفِّ صار الشر أعظم.\nوذكر ابنُ الصلاح رحمة الله عليه أنَّ الغناء إذا قام له شيءٌ من آلات اللهو حرم بالإجماع، أما بدون آلات الملاهي بل غناء مجرد فهو محرَّم عند غالب أهل العلم، وعند أكثر أهل العلم، وبعضهم حكى فيه إجماع أهل العلم، ولم يُبال بالمُخالف القليل، والأدلة مع مَن حرَّمه؛ لما فيه من الخُبث والضَّرر والشر الكثير، ولا سيما إذا كانت معه الموسيقى أو الكمان أو العود أو غير هذا من آلات اللهو؛ صار التَّحريمُ أشدَّ، وصار ذلك محلّ إجماعٍ ووفاقٍ بين أهل العلم.\nفيجب الحذر من هذه المُصيبة التي بُلي بها الناس، فيجب على المؤمن أن يُحذِّر من ذلك أهل بيته، وأن يجتهد في نصيحتهم؛ لعلهم يسلمون، لعلهم ينجون، والله المُستعان.","link":"https://binbaz.org.sa/fatwas/2747/ما-النصيحة-لمن-يستمع-الاغاني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0252.mp3","categories":["الشعر والأغاني"]},{"id":11,"question":"أما بعد، فقد ابتُليتُ بالغناء، ولقد علمتُ عن تحريم الغناء، ولكن قد تعوَّد عليه لساني، وكلما كففتُ عنه قليلًا أعود إليه لأسبابٍ كثيرةٍ؛ لأنني أستمع دائمًا الغناء، فأفيدوني عن ذلك أفادكم الله.","title":"بم يُنصح من لا يستطيع ترك سماع الغناء؟","answer":"الجواب: الغناء وآلات اللَّهو من بلية هذا الزمان، ومما ابتُلي به الناسُ في هذا العصر، فالواجب على المؤمن أن يُجاهد نفسه، فهو يجده في التلفاز، ويجده في الإذاعة، ويجده في بعض الأشرطة، إلى غير ذلك، فينبغي له أن يُجاهد نفسه، وليس بعذرٍ له كونه اعتاد ذلك، فينبغي له أن يُجاهد نفسه، فهذه الدار دار الجهاد، دار العمل، فلا بدّ من مُجاهدةٍ للنفس في كلِّ ما تعتاده من محارم الله حتى تدع ذلك، كما أنه لا بدّ من جهادها في أداء ما فرض الله، فلو طاوع نفسه ما صلَّى الفجر، ولو طاوع نفسه ما صلَّى الظهر إذا شُغل عن ذلك، ولو طاوع نفسه لترك الفرائض الأخرى، ولو طاوع نفسه لم يصم في الصيف، إلى غير ذلك.\nفلا بدّ من جهادٍ، فهذه الدار دار العمل، لا بدّ من جهاد النفس في أداء فرائض الله، وجهادها في الكفِّ عن محارم الله، وإذا كان هو يتعاطى الغناء كذلك يمنعها ويُجاهدها، لا بدّ من جهادٍ، قال تعالى: وَأَمَّا مَنْ خَافَ مَقَامَ رَبِّهِ وَنَهَى النَّفْسَ عَنِ الْهَوَى ۝ فَإِنَّ الْجَنَّةَ هِيَ الْمَأْوَى [النازعات:40- 41].\nفالمسألة تحتاج إلى جهادٍ، فإذا طاوع الإنسانُ نفسَه وأعطاها زمامَها أهلكته، فعلى المؤمن أن يُجاهد، فإذا بُلي بالتلفاز لا يسمع إلا ما ينفع مما أباح الله، ولا يتساهل مع رؤيته ومُشاهدته وسماعه ما حرَّم الله، وإذا بُلي بالإذاعة كذلك يسمع ما يُفيده وينفعه، ثم يُغلق المذياع عمَّا حرم الله، وهكذا في الصَّحافة، وهكذا في الأشرطة يسمع ما يُفيده، ويحذر ما يضرُّه، وليس له عذرٌ أن يقول: أنا اعتدتُ هذا، أو: نفسي أمرت بهذا، لا، مَن أطاع نفسه هلك: إِنَّ النَّفْسَ لَأَمَّارَةٌ بِالسُّوءِ إِلَّا مَا رَحِمَ رَبِّي [يوسف:53].","link":"https://binbaz.org.sa/fatwas/2790/بم-ينصح-من-لا-يستطيع-ترك-سماع-الغناء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0263.mp3","categories":["الشعر والأغاني"]},{"id":88,"question":"لقد درجت وشاعت بعضُ العادات عند القبائل بإحضار مَن يُسَمَّون: شُعراء المحاورة، مثل: أن يأتوا بشاعرين في حفلات العُرس ونحوها، كل واحدٍ منهما من قبيلةٍ، مقابل إعطائهما مبلغًا من المال، ويقوم الشاعران بإحياء الليل كما يقولون، حيث يكون هناك صفَّان مُتقابلان من الرجال، وكل شاعرٍ له صفٌّ، يُرددون ترديدًا جماعيًّا ما يقوله الشَّاعران، بأصواتٍ عاليةٍ، مع التَّصفيق والرقص والتَّمايل، ويفتخر كل شاعرٍ بحسبه ونسبه، ويطعن بالمُقابل في الشاعر الآخر، فما الحكم في هذا كله؟","title":"حكم الشعر بالأعراس مع الرقص والتصفيق","answer":"الجواب: أمَّا الغناء في العُرس من النِّساء بالدُّفوف فهذا من إعلان النكاح، فمشروعٌ ضرب الدف في النكاح للنساء خاصةً، وليس فيه اختلاطٌ، ويكون بالأغاني العادية التي ليس فيها منكر، فهذا مشروعٌ للنساء، وهو من إعلان النكاح، وكان يُفْعَل في عهد النبي ﷺ ويحضره أزواجُه وغيرُهم.\nأما الرجال فلا بأس أن يتعاطوا الشعر العربي، ويجتمعوا عليه ويسمعونه، وهو الذي ليس فيه محذور، وليس فيه غيبة، ولا سبٌّ، ولا شتمٌ، ولا يُسبب الشَّحناء والعداوة، وبدون طبلٍ، وبدون أي منكرٍ آخر من: عيب الناس، أو عيب قبيلة فلان مما يُسبب الشَّحناء، فهذا لا يجوز. أما إذا حضَّروا شعرًا طيبًا: كشعر حسان، والأشعار الطيبة، والقصائد الطيبة التي فيها الخير والدَّعوة إليه، أو قام شاعرٌ يدعوهم إلى الخير: إلى الجود والكرم والأعمال الطيبة، وقام شاعرٌ آخر كذلك يدعو إلى الخير ومكارم الأخلاق ومحاسن الأعمال؛ فلا بأس، وكما قال ﷺ: إنَّ من الشعر لحكمةً، وقال لحسان: اهجُ الكفار، فوالذي نفسي بيده، إنه لأشدّ عليهم من وقع النَّبْل، وقال: اللهم أيِّده بروح القدس، فكان حسانُ يهجوهم، وكانت أشعاره عظيمةً طيبةً، وهكذا عبدالله بن رواحة، وكعب بن مالك، وهكذا مَن بعدهم من الشُّعراء الطيبين.\nومن الشعر: \"نونية ابن القيم\" التي هي من أعظم الشعر وأنفعه، فهي قصيدة طيبة عظيمة نافعة، و\"نونية القحطاني\"، وهي قصيدة طيبة نافعة في العقيدة، وهكذا الأشعار الطيبة التي فيها الدَّعوة إلى الخير وإلى مكارم الأخلاق ومحاسن الأعمال، فهذا طيبٌ في العرس وغير العرس.\nأما أن يقوم شاعران أو أكثر يتناحرون، ويذمّ بعضُهم بعضًا، ويسبُّ بعضُهم بعضًا، أو يسبُّ هذا قبيلةَ هذا، وقبيلةَ هذا؛ فهذا منكر، لكن إذا كان الشعرُ فيما ينفع الناس؛ كالدَّعوة إلى مكارم الأخلاق، ومحاسن الأعمال، وبرّ الوالدين، وصلة الرحم، وطاعة الله ورسوله، وطاعة ولاة الأمور بالمعروف، والحذر من معاصي الله؛ فهذا كله طيبٌ، وله أثرٌ في النفوس.\nولا بأس أن تُعطى المغنية في العُرس أجرةً على عملها، أو الشاعر الذي عنده أشعار طيبة، فيُدْعَى ليقول الشعر الطيب الذي ينفع الناس، ويُعْطَى جائزةً، لا بأس بذلك.\nأما الذي يدعو إلى غيبة فلان، وذمِّ فلان، ومدح فلان؛ لإثارة الشَّحناء والعداوة والبغضاء بين الناس، فهذا منكرٌ لا يجوز -نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/3091/حكم-الشعر-بالاعراس-مع-الرقص-والتصفيق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0065.mp3","categories":["الشعر والأغاني","الزفاف ووليمة العرس"]},{"id":131,"question":"هذه مجموعة أسئلة.. تسأل عن العَرْضَة؟","title":"ما حكم \"العَرْضَة\" ونحوها؟","answer":"الجواب: العرضات إذا كانت لا تمنع من الصلاة ولا تشغل عنها، وليس فيها اختلاط الرجال بالنساء، وفيها اختلاط بالرجال خاصةً، وليس فيها ما يُنْكَر، بالأشعار العربية، أشعار تدعو إلى الجود والكرم والحماس والشجاعة ونحو ذلك، وليس فيها منكر: لا موسيقى، ولا طبول؛ فلا بأس. أما إذا كانت فيها موسيقى وآلات ملاهٍ من طبول وموسيقى، وكانت تشغل عن الصلاة، أو فيها محذورات أخرى، منكرات أخرى: من كشف عورات؛ لا تحضر، لا يجوز حضورها، إلا إذا كانت سليمة: أشعار سليمة، ومجالس سليمة، ولا تشغل عن الصلاة، وليس فيها من آلات الملاهي شيء، لا بأس.","link":"https://binbaz.org.sa/fatwas/3658/ما-حكم-العرضة-ونحوها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0120.mp3","categories":["الشعر والأغاني","الزفاف ووليمة العرس"]},{"id":360,"question":"هل الشعر حرام؟ مع أن حُجّة بعض الناس أن الرسول ﷺ كان له شاعرٌ، وهو حسَّان بن ثابت.","title":"ما الحكم الشرعي في الشعر والشعراء؟","answer":"الجواب: هذا فيه تفصيل أيضًا، والشعر مثلما قال الشافعي رحمه الله: \"حسنه حسن، وقبيحه قبيح\"، فالشعر الذي ينصر الحقَّ ويُؤيد الحقَّ، ويهدم الباطل وأهل الباطل؛ هذا مطلوبٌ، هذا مشروعٌ، وهو الذي كان يقوم به حسان بن ثابت ، وعبدالله بن رواحة، وسعد بن مالك، وغيرهم من الشعراء الذين كانوا في عهده ﷺ وبعده.\nأما إذا كان الشعر في ذمِّ الحق، ومدح الخنا والفساد، والدعوة إلى الزنا والفجور؛ فهذا منكرٌ محض لا يجوز.\nفالشعر يختلف بحسب مقاصده ومراد صاحبه: فإن أراد الحقَّ والخير ومُقتضى شعره يدل على ذلك؛ فلا بأس في ذلك، ومن الدعوة إلى الخير، والدعوة إلى الحق، وإن كان شعره يدعو إلى الباطل والفساد؛ صار مذمومًا يجب منعه منه.","link":"https://binbaz.org.sa/fatwas/4554/ما-الحكم-الشرعي-في-الشعر-والشعراء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0413.mp3","categories":["الشعر والأغاني","الزفاف ووليمة العرس"]},{"id":760,"question":"الأناشيد الإسلامية هل تدخل في الغناء أم لا؟","title":"ما حكم الأناشيد الإسلامية؟","answer":"الجواب: إذا كانت سليمةً ليس فيها شيءٌ من جنس الشعر: حَسَنُها حسن، وقبيحُها قبيح، فالأناشيد الإسلامية التي تُلقى بأصوات العرب، لا بأصوات النساء، ولا بأصواتٍ تُثير شرًّا، بل بأصواتٍ عربيةٍ إسلاميةٍ، وليس فيها محذورٌ؛ من جنس بقية الشعر: إنَّ من الشعر لحكمة، فالأشعار السليمة بمكارم الأخلاق ومحاسن الأعمال لا بأس بها، وقد أنشد حسان بن ثابتٍ  بين يدي النبي ﷺ هجوه للمشركين، فأقرَّه النبيُّ ﷺ وأمره أن يهجوهم وقال: إنَّ روح القدس معك، وقال: إنه لأشد عليهم من وقع النَّبْل، وهكذا سمع شعر كعب بن مالك، وشعر عبدالله بن رواحة.","link":"https://binbaz.org.sa/fatwas/20684/ما-حكم-الاناشيد-الاسلامية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0585حكم النشيد الإسلامي؟ ابن باز رحمه الله فتاوى المحاضرات.mp3","categories":["الشعر والأغاني","الزفاف ووليمة العرس"]},{"id":911,"question":"ما حكم حضور حفلات الزفاف التي يوجد فيها الغناء، سواء من الرجال أو من النِّساء؟","title":"حكم حضور حفلات الزفاف التي بها غناء","answer":"الجواب: حفلات الزواج فيها تفصيلٌ: إذا كانت الحفلة مصونةً شرعيةً فلا بأس، يحضرها الرجال والنساء، النساء مع النساء، والرجال مع الرجال. وإذا كانت فيها ما حرَّم الله وجب الامتناعُ، فإذا كان فيها اختلاطُ الرجال بالنساء؛ لم يجز للمرأة أن تحضر معهم، ووجب على أهل الزواج إنكار ذلك، ووجب على الحِسبة إنكار ذلك، حتى لا يحصل هذا الاختلاط.\nكذلك إذا كانت فيها الملاهي: من العود والكمان والطبول؛ وجب المنع. أما الدُّفّ العادي بين النساء فلا بأس، الدُّف الذي له وجهٌ واحدٌ -وهو الطار- تضرب به النساء خاصةً بينهنَّ في ليلة العُرْس؛ لا بأس، هذا يفعل في عهد النبي ﷺ وعهد أصحابه لإعلان النكاح وإظهاره، أما أن يستعمل غير ذلك من الطبول والعود وأشباه ذلك من آلات الملاهي، أو اختلاط النساء بالرجال؛ هذا شيء يضرُّ الناس، وهو منكرٌ، وربما سبب إضاعة الصلاة -صلاة الفجر- بسبب السهر، فهذا لا يجوز.\nفالمقصود أنَّ على أهل العُرْس أن يكون اجتماعُهم وحفلُهم متقيدًا بالشريعة، في بعض الليل؛ حتى يناموا، وحتى لا يُضيِّعوا الفجر.","link":"https://binbaz.org.sa/fatwas/20948/حكم-حضور-حفلات-الزفاف-التي-بها-غناء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0744ما حكم حضور حفلات الزفاف التي يوجد فيها الغناء سواء من الرجال أو من النساء ؟ ابن باز.mp3","categories":["الشعر والأغاني","الزفاف ووليمة العرس"]},{"id":941,"question":"ما حكم الأناشيد؟ لأنَّ كثيرًا من الشباب يستمعون إليها ويتركون القرآن، أو يستمعون لها أكثر مما يستمعون إلى القرآن، وإذا كانت تجوز بشروطٍ فما شروطها؟","title":"ما حكم الأناشيد؟ وما شروطها؟","answer":"الجواب: الأناشيد من جنس الشعر: حسنه حسن، وقبيحه قبيح، إذا كانت أناشيد سليمة، معانيها طيبة؛ لا بأس بها، وإن كانت أناشيد رديئة، ومعانيها رديئة؛ مُنِعَتْ، فهي من جنس الشعر، فإذا كانت الأناشيد في مدح الخمور، أو الدَّعوة إلى الفواحش، أو ما أشبه ذلك؛ فهذه تُمنع، أما إذا كانت أناشيد في الحثِّ على العلم، وطلب العلم، وبرِّ الوالدين، وصلة الرحم، والمحافظة على الصلاة، وأشباه ذلك؛ فهي مقبولة.","link":"https://binbaz.org.sa/fatwas/20972/ما-حكم-الاناشيد-وما-شروطها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0768ما حكم الأناشيد؟ ابن باز فتاوى المحاضرات.mp3","categories":["الشعر والأغاني","الزفاف ووليمة العرس"]},{"id":1178,"question":"أحد الباحثين قام بعمل بحثٍ حول الغناء وآلات العزف، وقال: إنَّ رأيه قد استقرَّ على إباحة ذلك كله، فما رأي سماحتكم؟","title":"ما الرد على من يرى إباحة الغناء والمعازف؟","answer":"الجواب:\n\nهذا فيه تفصيل:\n\nأما الشعر العربي المعروف فهذا لا بأس به إذا كان معناه الدَّعوة إلى الله، أو التَّشجيع على الكرم والجود والأعمال الطيبة، أو الجهاد، أو هجو الأعداء، أو الحث على الجهاد، أو نحو ذلك، مثلما كان يفعل حسانُ وكعبُ بن مالك وعبدُالله بن رواحة وغيرُهم، هذا أمرٌ مُسلَّمٌ، وهكذا النَّشيد فيما ينصر الحقَّ، كما كان النبيُّ يفعل والصحابة لما كانوا يحفرون الخندق، وفي بناء مسجده ﷺ:\n\n\n\t\n\t\t\n\t\t\tاللهم لولا أنت ما اهتدينا\n\t\t\tولا تصدَّقنا ولا صلَّينا\n\t\t\n\t\t\n\t\t\tفأنزلن سكينةً علينا\n\t\t\tوثبِّت الأقدامَ إن لاقينا\n\t\t\n\t\n\nهذا كله طيب.\nأما آلات الملاهي أو الغناء المعروف الذي يُشبه غناء النِّساء بالتَّكسر وألحان النساء؛ فهذا محرَّمٌ عند جمهور أهل العلم، ذهب قلَّةٌ إلى جواز الشيء اليسير منه، ولكن الأكثرين من أهل العلم على تحريمه مطلقًا، وإذا كان يدعو إلى خمر أو زنا أو فواحش حَرُم بالإجماع، لكن إذا كانت صيغته تدعو إلى شهوة النِّساء وإلى المعاصي حَرُم ذلك، وإذا كان بأصوات النِّساء حَرُم ذلك؛ لأنَّ الله قال: فَلَا تَخْضَعْنَ بِالْقَوْلِ فَيَطْمَعَ الَّذِي فِي قَلْبِهِ مَرَضٌ [الأحزاب:32]، فيحرم على الرجال سماعه، أما بينهنَّ فلا بأس، بين النساء في العرس لا بأس، كما جاء عن النبي ﷺ، مع الدُّفِّ، أو الجواري في أيام العيد بالأشعار التي لا محذور فيها، كما أقرَّ النبيُّ الجاريتين على الشعر في بيت عائشة، بأشعار الأنصار يوم بُعاث في يوم عيدٍ، وقال: إنه يوم عيد، وأمر الصديقَ قال: دعهما، هذا لا بأس به.\nوقال ابنُ الصلاح: أجمع العلماء على أنَّ الغناء مع بعض آلات اللَّهو مُحرَّمٌ بالإجماع، وإنما الخلاف إذا كان الغناء فقط، ليس معه شيء، الجمهور على تحريمه مطلقًا: الغناء الذي يصدر من النساء، أو من الرجال على طريقة النساء، أما الأشعار العربية بلغة العرب ولحون العرب فهذا جائزٌ ما فيه خلاف، وفعله حسانُ بين يدي النبي ﷺ، وفعله كعب بن مالك، وفعله عبدالله بن رواحة، وهكذا النَّشيد الصالح الذي يدعو إلى الخير بين الرجال، كما فعلوا يوم الخندق، وكما فعلوا في بناء مسجد النبي ﷺ فلا يجوز الخلط والتَّلبيس.\nأما آلات الملاهي فكلها محرَّمة: العود، والكمان، والموسيقى، والطبل، آلات الملاهي ما فيها تفصيل، كلها منكرة، وقد كتبنا في هذا رسالةً مُستقلةً، لها مدة طويلة تُوزَّع، أوضحنا فيها الأدلة بالتفصيل، فنرجو أن تُنشر قريبًا في الصحف؛ لأجل شمول الفائدة، وكذلك تُطبع وتُوزَّع إن شاء الله، هي قد طُبعت مرات كثيرة، ووزِّعَت مرات كثيرة، لكن الحاجة ماسَّة الآن إلى توزيعها في كل مكانٍ.","link":"https://binbaz.org.sa/fatwas/21254/ما-الرد-على-من-يرى-اباحة-الغناء-والمعازف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1140أحد الباحثين قام بعمل بحث حول العناء وآلآت العزف وقال قد استقر على أباحة كله فما رأيكم.mp3","categories":["الشعر والأغاني","الزفاف ووليمة العرس"]},{"id":1835,"question":"اتِّخاذ الشعر؟","title":"ما حكم اتِّخاذ الشعر وإطالته؟","answer":"الجواب:\nلا بأس به إذا لم يكن فيه مفسدة، أما إذا اتَّخذه للفساد وتَصَيُّد النساء والفاحشة فيَحْرُم، أما إذا اتَّخذه للتَّسَنُّن وأنه يقصد الخير والسنة فلا بأس.\nس: الشعر الطويل للرجال سُنَّة؟\nج: إذا أخذه بنيةٍ صالحةٍ، ما هو بنية التلاعب والفساد في الأرض.\nس: سُنَّة؟\nج: جائز.\nس: إطالته إطالةً واضحةً؟\nج: ليس هناك حدٌّ محدودٌ، لكن لا يكون قصده خبيثًا.","link":"https://binbaz.org.sa/fatwas/21943/ما-حكم-اتخاذ-الشعر-واطالته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم اتِّخاذ الشعر وإطالته.mp3","categories":["الشعر والأغاني","الزفاف ووليمة العرس"]},{"id":2855,"question":"بعض الأناشيد فيها طُبُول، هل يعتبر هذا الفعل من فعل الصوفية؟","title":"حكم الأناشيد التي فيها طُبُول","answer":"الجواب: الطَّبْل من آلات الملاهي، ما يجوز.\nس: إذا كان ما فيها شيء، ما فيها طبول؟\nالشيخ: إذا كان ما فيها محذور شرعًا، أشعار عربية تدعو إلى خير أو تأمر بخير؛ ما في بأس، أما إذا كانت أناشيد أو أشعار تدعو إلى الباطل؛ فهي ممنوعة.\nس: يؤدون هذه الأناشيد بإيقاعات موسيقية أشبه بإيقاعات أصحاب الأغاني؟\nالشيخ: المقصود إذا كانت ما فيها محذور؛ لا حرج.","link":"https://binbaz.org.sa/fatwas/23008/حكم-الاناشيد-التي-فيها-طبول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الأناشيد التي فيها طبول.mp3","categories":["الشعر والأغاني","الزفاف ووليمة العرس"]},{"id":3968,"question":"قول عامر في شعره: فاغفر فداء لك؟","title":"مَنْ يعني عامرٌ في شعره: فاغفر فداء لك؟","answer":"الجواب: ما فيه شيء، المقاتلون كلهم فداء له ، المقاتل في سبيل الله كذلك؛ لأن المقصود أفدي طاعتك وما شرعت له وما جاء به رسولك ﷺ، فالفداء لله فداء لدينه وفداء لشرعه.","link":"https://binbaz.org.sa/fatwas/24196/من-يعني-عامر-في-شعره-فاغفر-فداء-لك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من يخاطب عامر في شعره فاغفر فداء لك.mp3","categories":["الشعر والأغاني","الزفاف ووليمة العرس"]},{"id":5129,"question":"سائل يقول: لقد درجت وشاعت بعضُ العادات عند القبائل بإحضار مَن يُسَمَّون: شُعراء المحاورة، مثل: أن يأتوا بشاعرين في حفلات العُرس ونحوها، كل واحدٍ منهما من قبيلةٍ، مقابل إعطائهما مبلغًا من المال، ويقوم الشاعران بإحياء الليل كما يقولون، حيث يكون هناك صفَّان مُتقابلان من الرجال، وكل شاعرٍ له صفٌّ، يُرددون ترديدًا جماعيًّا ما يقوله الشَّاعران، بأصواتٍ عاليةٍ، مع التَّصفيق والرقص والتَّمايل، ويفتخر كل شاعرٍ بحسبه ونسبه، ويطعن بالمُقابل في الشاعر الآخر، فما الحكم في هذا كله؟","title":"ما حكم إحضار شُعراء المحاورة في الأعراس؟","answer":"الجواب: أمَّا الغناء في العُرس من النِّساء بالدُّفوف فهذا من إعلان النكاح، فمشروعٌ ضرب الدف في النكاح للنساء خاصةً، وليس فيه اختلاطٌ، ويكون بالأغاني العادية التي ليس فيها منكر، فهذا مشروعٌ للنساء، وهو من إعلان النكاح، وكان يُفْعَل في عهد النبي ﷺ ويحضره أزواجُه وغيرُهم. أما الرجال فلا بأس أن يتعاطوا الشعر العربي، ويجتمعوا عليه ويسمعونه، وهو الذي ليس فيه محذور، ليس فيه غيبة، ولا سبٌّ، ولا شتمٌ، ولا يُسبب الشَّحناء والعداوة، بدون طبلٍ، وبدون أي منكرٍ آخر من: عيب الناس، أو عيب قبيلة فلان مما يُسبب الشَّحناء، فهذا لا يجوز، أما إذا حضَّروا شعرًا طيبًا: كشعر حسان، والأشعار الطيبة، والقصائد الطيبة التي فيها الخير والدَّعوة إليه، أو قام شاعرٌ يدعوهم إلى الخير: إلى الجود والكرم والأعمال الطيبة، وقام شاعرٌ آخر كذلك يدعو إلى الخير ومكارم الأخلاق ومحاسن الأعمال؛ فلا بأس، وكما قال ﷺ: إنَّ من الشعر لحكمةً، وقال لحسان: اهجُ الكفار، فوالذي نفسي بيده، إنه لأشدّ عليهم من وقع النَّبْل، وقال: اللهم أيِّده بروح القدس، فكان حسانُ يهجوهم، وكانت أشعاره عظيمةً طيبةً، وهكذا عبدالله بن رواحة، وكعب بن مالك، وهكذا مَن بعدهم من الشُّعراء الطيبين. ومن الشعر: \"نونية ابن القيم\" التي هي من أعظم الشعر وأنفعه، فهي قصيدة طيبة عظيمة نافعة، و\"نونية القحطاني\"، وهي قصيدة طيبة نافعة في العقيدة، وهكذا الأشعار الطيبة التي فيها الدَّعوة إلى الخير وإلى مكارم الأخلاق ومحاسن الأعمال، فهذا طيبٌ في العرس وغير العرس. أما أن يقوم شاعران أو أكثر يتناحرون، ويذمّ بعضُهم بعضًا، ويسبُّ بعضُهم بعضًا هذا منكر، أو يسبُّ هذا قبيلةَ هذا، وقبيلةَ هذا؛ هذا منكر، لكن إذا كان الشعرُ فيما ينفع الناس؛ كالدَّعوة إلى مكارم الأخلاق، ومحاسن الأعمال، وبرّ الوالدين، وصلة الرحم، وطاعة الله ورسوله، وطاعة ولاة الأمور بالمعروف، والحذر من معاصي الله؛ فهذا كله طيبٌ، وله أثرٌ في النفوس. ولا بأس أن تُعطى المغنية في العُرس أجرةً على عملها، أو الشاعر الذي عنده أشعار طيبة، فيُدْعَى ليقول الشعر الطيب الذي ينفع الناس، ويُعْطَى جائزةً، لا بأس بذلك. أما الذي يدعو إلى غيبة فلان، وذمِّ فلان، ومدح فلان؛ لإثارة الشَّحناء والعداوة والبغضاء بين الناس، فهذا منكرٌ لا يجوز -نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/30044/ما-حكم-احضار-شعراء-المحاورة-في-الاعراس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 65.mp3","categories":["الشعر والأغاني","الزفاف ووليمة العرس"]},{"id":5170,"question":"هذه مجموعة أسئلة تسأل عن العرضة، وحكم إعطاء المال للشعراء، وأسئلة أخرى تسأل عمَّا يُسمَّى بشعر الرد، يعني: بدون عرضة؟","title":"حكم \"العرضة\" والطبول وإعطاء المال للشعراء","answer":"الجواب: العرضات إذا كانت لا تمنع من الصلاة ولا تشغل عنها، وليس فيها اختلاط الرجال بالنساء، وفيها اختلاط بالرجال خاصةً، وليس فيها ما يُنْكَر، بالأشعار العربية، أشعار تدعو إلى الجود والكرم والحماس والشجاعة ونحو ذلك، وليس فيها منكر: لا موسيقى، ولا طبول؛ فلا بأس. أما إذا كانت فيها موسيقى وآلات ملاهٍ من طبول وموسيقى، وكانت تشغل عن الصلاة، أو فيها محذورات أخرى، منكرات أخرى: من كشف عورات؛ لا تحضر، لا يجوز حضورها، إلا إذا كانت سليمة: أشعار سليمة، ومجالس سليمة، ولا تشغل عن الصلاة، وليس فيها من آلات اللهو شيء، لا بأس. س: التطبيل يا شيخ؟ الشيخ: الطبل لا يصلح، وفي الحديث الصحيح يقول ﷺ: إن الله حرَّم عليكم الخمرَ والميسرَ والكوبة، قال الراوي: والكوبة هي الطبل.","link":"https://binbaz.org.sa/fatwas/30095/حكم-العرضة-والطبول-واعطاء-المال-للشعراء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 120.mp3","categories":["الشعر والأغاني","الزفاف ووليمة العرس"]},{"id":5286,"question":"طالبات في حفل مدرسي أو في فرح ينشدن الشعر بشكل جماعي من أجل تقوية الصوت فقط، وهذا النشيد بعيد عن التلحين الغنائي فما الحكم في ذلك، وهل هناك فرق بين النشيد الجماعي والنشيد الفردي؟","title":"هل يجوز النشيد بصوت جماعي للفتيات؟","answer":"الجواب: النشيد طيِّبُه طيب، وخبيثُه خبيث، إن كان يتضمن الدعوة إلى الخير وإلى الإصلاح وإلى التقوى فهو مثل الشعر إن من الشعر حكمة وإن كان نشيدًا فيه أشياء منكرة صار مذمومًا كالشعر المذموم، يقول ﷺ: إن من الشعر حكمة، وكان ﷺ يسمع شعر حسان؛ لأنه شعر يدعو إلى طاعة الله واتباع شريعته وتصديق النبي ﷺ، وابن رواحة، وابن أبي أوفى، وكعب بن مالك، وغيرهم؛ لأنها أشعار مفيدة. أما الأشعار التي تدعو إلى الباطل أو تثبِّط عن الطاعات أو تدعو إلى الفحش فهي محرّمة، وهكذا النشيد إن كان على خير فهو طيب، وإن كان على شر فهو مذموم. السؤال: بشكل جماعي؟ الشيخ: أما إذا كان للتعليم كونه يعلّمهم ويقرؤون جميعًا؛ لا بأس من باب التعليم أما التعبد بذلك لا، ما هو مشروع ... ولا في الأذكار ولا في غيرها، كُلٌّ يذكر الله على حسب حاله من غير رفع صوته على الآخر، لكن يذكر الله على حسب التيسير .. أما المعلم إذا كان معه أربعة أو خمسةحتى يتقنوا ما يقول لهم من باب التعليم؛ فلا بأس ولا حرج في ذلك.[1]","link":"https://binbaz.org.sa/fatwas/30924/هل-يجوز-النشيد-بصوت-جماعي-للفتيات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 005.mp3","categories":["الشعر والأغاني","الزفاف ووليمة العرس"]},{"id":5853,"question":"أحد الإخوة جاء بقصاصة مصورة لبعض الجرئد اليومية، ومكتوب في ركنها ركن الفتاوى: ما حكم الإسلام في سماع الموسيقى؟ وهل سمعها، أو تعليمها حلال، أو حرام؟ الإجابة: الإنسان عاطفي بطبعه، والشرائع السماوية لا تقتل في الإنسان غرائزه، ولا تميت فيه عاطفة، ولكن مهمتها في هذه الناحية كبح الجماح، والحد من الاندفاع الذي يخرج الإنسان عن الحد اللائق، وظل يتكلم في هذا الموضوع  إلى أن قال: والاستماع إلى الموسيقى على هذا الوجه مباح، ومشروع أخذًا بما روته السنة من أن الرسول ﷺ مر على قوم يعزفون بالدف، ويعزفون بالموسيقى، ويرددون الأغاني في مناسبة عرس، وكان في صحبته عمر، فلما أراد عمر منعهم، قال -صلوات الله عليه-: دعهم فإن هذا يفرق بين النكاح، والسفاح. فما رأي سماحتكم؟","title":"حكم سماع الغناء وآلات اللهو","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله، وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فلا شك أن هذه الفتوى غلط من قائلها، ولا ريب أن سماع الموسيقى، وآلات الملاهي من المنكرات، وقد حكى بعض أهل العلم: إجماع أهل العلم على أن سماع الغناء، وآلات اللهو إذا اجتمعا فهو من المحرمات بالإجماع.  وقد دلت السنة على أن المعازف من المحرمات التي يستحلها الناس في آخر الزمان، ثبت عنه ﷺ أنه قال: ليكونن من أمتي أقوام يستحلون الحر، والحرير، والخمر، والمعازف يعني في آخر الزمان، رواه البخاري في الصحيح معلقًا مجزومًا، والحرّ هو الفرج الحرام، يعني: الزنا، والخمر معروف، والمعازف هي آلات الملاهي، والحرير معروف، محرم على الرجال دون النساء، فأخبر النبي ﷺ أنه يكون في آخر الزمان قوم يستحلون هذا وهذا، يستحلون الزنا، ويستحلون لبس الحرير من الرجال، ويستحلون الخمر، ويستحلون المعازف، وهي الغناء، وآلات الملاهي، ولا شك أن الموسيقى من آلات الملاهي، ومن المطربات. والذي أحله النبي ﷺ هو ما يتعلق بالنساء في العرس، الغناء العادي الذي لا يدعو إلى الفساد؛ بل غناء الناس فيما بينهم مع دف للنساء في الأعراس، أو من الجواري الصغار في الأعياد، هذا هو الذي جاء عن النبي ﷺ حله، أما للرجال فلا. والمقصود: أنه ﷺ أحل أيضًا للحبشة اللعب في المسجد بآلات السلاح بالدرقة، والسيوف، والرماح التي تقذف، وأشباه ذلك من باب التدرب على الحرب، وآلات الملاهي، ولما أراد عمر أن ينكر عليهم ذلك قال: دعهم حتى تعلم اليهود أن في ديننا فسحة وفي قصة الجواري: دعهم فإن لكل قوم عيدًا. فالمقصود: أن التدرب على آلات الحرب، كالسلاح، ورمي الدرق، واتقاء سيوف الدرق، وما أشبه ذلك؛ هذا من الأمور المطلوبة شرعًا للإعداد للقتال، والتأهب للقتال، والتدرب على آلات القتال في المسجد، وغيره. أما سماع آلات الملاهي من الموسيقى، أو العود، أو الكمان، أو غير هذا من أنواع آلات الملاهي، فهذا لا شك أنه منكر، ومن أسباب ضعف الإيمان، ومن أسباب موت الغيرة في القلوب، ولا شك أن الذي أحله النبي ﷺ إنما هو شيء يتعلق بالنساء، والأعراس حتى يعلم الفرق بين السفاح، والنكاح، فالسفاح يكون بالخلوة، والفواحش، والنكاح يكون بالعلن، ويكون بالدف للنساء، والغناء العادي للنساء، لا فيما يتعلق بالأغاني التي تدعو إلى الفواحش، والمنكرات، والخمر، وغير ذلك، والله المستعان.","link":"https://binbaz.org.sa/fatwas/1195/حكم-سماع-الغناء-والات-اللهو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_191.mp3","categories":["الشعر والأغاني","النجاسات وإزالتها"]},{"id":5858,"question":"أحد الإخوة جاء بقصاصة مصورة لبعض الجرئد اليومية، ومكتوب في ركنها ركن الفتاوى: ما حكم الإسلام في سماع الموسيقى؟ وهل سمعها، أو تعليمها حلال، أو حرام؟ الإجابة: الإنسان عاطفي بطبعه، والشرائع السماوية لا تقتل في الإنسان غرائزه، ولا تميت فيه عاطفة، ولكن مهمتها في هذه الناحية كبح الجماح، والحد من الاندفاع الذي يخرج الإنسان عن الحد اللائق، وظل يتكلم في هذا الموضوع  إلى أن قال: والاستماع إلى الموسيقى على هذا الوجه مباح، ومشروع أخذًا بما روته السنة من أن الرسول ﷺ مر على قوم يعزفون بالدف، ويعزفون بالموسيقى، ويرددون الأغاني في مناسبة عرس، وكان في صحبته عمر، فلما أراد عمر منعهم، قال -صلوات الله عليه-: دعهم فإن هذا يفرق بين النكاح، والسفاح. فما رأي سماحتكم؟","title":"حكم سماع الغناء وآلات اللهو","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله، وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فلا شك أن هذه الفتوى غلط من قائلها، ولا ريب أن سماع الموسيقى، وآلات الملاهي من المنكرات، وقد حكى بعض أهل العلم: إجماع أهل العلم على أن سماع الغناء، وآلات اللهو إذا اجتمعا فهو من المحرمات بالإجماع.  وقد دلت السنة على أن المعازف من المحرمات التي يستحلها الناس في آخر الزمان، ثبت عنه ﷺ أنه قال: ليكونن من أمتي أقوام يستحلون الحر، والحرير، والخمر، والمعازف يعني في آخر الزمان، رواه البخاري في الصحيح معلقًا مجزومًا، والحرّ هو الفرج الحرام، يعني: الزنا، والخمر معروف، والمعازف هي آلات الملاهي، والحرير معروف، محرم على الرجال دون النساء، فأخبر النبي ﷺ أنه يكون في آخر الزمان قوم يستحلون هذا وهذا، يستحلون الزنا، ويستحلون لبس الحرير من الرجال، ويستحلون الخمر، ويستحلون المعازف، وهي الغناء، وآلات الملاهي، ولا شك أن الموسيقى من آلات الملاهي، ومن المطربات. والذي أحله النبي ﷺ هو ما يتعلق بالنساء في العرس، الغناء العادي الذي لا يدعو إلى الفساد؛ بل غناء الناس فيما بينهم مع دف للنساء في الأعراس، أو من الجواري الصغار في الأعياد، هذا هو الذي جاء عن النبي ﷺ حله، أما للرجال فلا. والمقصود: أنه ﷺ أحل أيضًا للحبشة اللعب في المسجد بآلات السلاح بالدرقة، والسيوف، والرماح التي تقذف، وأشباه ذلك من باب التدرب على الحرب، وآلات الملاهي، ولما أراد عمر أن ينكر عليهم ذلك قال: دعهم حتى تعلم اليهود أن في ديننا فسحة وفي قصة الجواري: دعهم فإن لكل قوم عيدًا. فالمقصود: أن التدرب على آلات الحرب، كالسلاح، ورمي الدرق، واتقاء سيوف الدرق، وما أشبه ذلك؛ هذا من الأمور المطلوبة شرعًا للإعداد للقتال، والتأهب للقتال، والتدرب على آلات القتال في المسجد، وغيره. أما سماع آلات الملاهي من الموسيقى، أو العود، أو الكمان، أو غير هذا من أنواع آلات الملاهي، فهذا لا شك أنه منكر، ومن أسباب ضعف الإيمان، ومن أسباب موت الغيرة في القلوب، ولا شك أن الذي أحله النبي ﷺ إنما هو شيء يتعلق بالنساء، والأعراس حتى يعلم الفرق بين السفاح، والنكاح، فالسفاح يكون بالخلوة، والفواحش، والنكاح يكون بالعلن، ويكون بالدف للنساء، والغناء العادي للنساء، لا فيما يتعلق بالأغاني التي تدعو إلى الفواحش، والمنكرات، والخمر، وغير ذلك، والله المستعان.","link":"https://binbaz.org.sa/fatwas/1195/حكم-سماع-الغناء-والات-اللهو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_191.mp3","categories":["الشعر والأغاني","النجاسات وإزالتها"]},{"id":5862,"question":"ما الفرق بين الدف، والطنبور؟","title":"الفرق بين الدف والطنبور","answer":"الجواب: معروف الطنبور، لكن بعض أهل العلم قال: إنه الطبل، وعلى كل حال فالدف مباح، وما سواه غير مباح، الدف للنساء هو المباح، والدف نوع يتخذ من الطيلان، له وجه واحد، لا يكون فيه حلق، ولا يكون فيه حديد تضربه النساء.   وأما الطنبور فجاء الحديث في النهي عنه، وهكذا الطبل، وهكذا سائر الملاهي، كلها محرمة.","link":"https://binbaz.org.sa/fatwas/1196/الفرق-بين-الدف-والطنبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_192.mp3","categories":["الشعر والأغاني","النجاسات وإزالتها"]},{"id":6030,"question":"هناك رجال على سيما الصلاح، ولكنهم يتابعون بعض الأغاني، والتمثيليات التلفزيونية، فهل عليهم حرج في ذلك؟","title":"سماع الأغاني ومشاهدة التمثيليات التلفزيونية","answer":"الجواب: استماع الأغاني، والتمثيليات الضارة، المخالفة للشرع تضر الجميع، تضر الذي يستمعها، وينظر إليها، أما إذا سمع الأحاديث الدينية، والقرآن، والأخبار المهمة؛ فلا يضره ذلك.","link":"https://binbaz.org.sa/fatwas/1427/سماع-الاغاني-ومشاهدة-التمثيليات-التلفزيونية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_367.mp3","categories":["الشعر والأغاني"]},{"id":6194,"question":"قد يبول الأطفال أحيانًا على فرش البيت، فهل يكتفى بوضع سجادة للصلاة فوق الفرش؟","title":"حكم الصلاة على سجادة تحتها فراش نجس","answer":"الجواب: إذا وضع على الفراش الذي فيه بول سجادة، وصلى عليها؛ لا بأس، وإذا غسل الموضع الذي أصابه البول، وصب عليه الماء حتى يكاثره؛ تطهر المكان، وإذا وضع السجادة، أو بساط طاهر على بسط نجسة؛ كفى ذلك.","link":"https://binbaz.org.sa/fatwas/1666/حكم-الصلاة-على-سجادة-تحتها-فراش-نجس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_545.mp3","categories":["الشعر والأغاني","النجاسات وإزالتها"]},{"id":6528,"question":"من المعروف بأن الغناء محرم، وإذا أردنا أن نفهم البعض بذلك احتجوا علينا، وقالوا: إن الغناء إذا كان حرامًا، لم يكن في التلفزيون والإذاعة، وفي الأسواق، فماذا نرد على هؤلاء، والبعض يقول: إن الذنب ذنب المغني، أو المغنية، أما المستمع فليس عليه شيء؟","title":"الرد على بعض شبهات المجيزين لاستماع الغناء","answer":"الجواب: الغناء محرم بلا شك، الأغاني شرها عظيم، وقد ذهب جمهور أهل العلم إلى تحريمها، وأن الواجب إنكارها، وإذا كان معها الموسيقى، أو غيرها من آلات اللهو؛ حرم هذا بإجماع المسلمين، قال الله -جل وعلا-: وَمِنَ النَّاسِ مَنْ يَشْتَرِي لَهْوَ الْحَدِيثِ لِيُضِلَّ عَنْ سَبِيلِ اللَّهِ بِغَيْرِ عِلْمٍ [لقمان:6] الآية، بين أهل العلم -جمهور المفسرين- على أن المراد بلهو الحديث: الغناء، وأصوات المعازف .. كلها داخل في ذلك، فهذا محرم عند أهل العلم، وإذا اجتمع الغناء، ومعه آلات اللهو من الكمان، أو العود، أو موسيقى، أو ما أشبه ذلك؛ حرم عند جميع أهل العلم.  فالواجب تركه، والمستمع شريك للمغني، ومن قال .. هذا غلط، فالمستمع شريك كما أن المستمع لقارئ القرآن شريك له في الأجر، فالمستمع للموسيقى والأغاني المنكرة شريك له في الوزر، فالأغاني، وأفلام الغناء، وكاستات الغناء يحرم بيعها، وشراؤها، واستماعها، كلها منكرة، وثمنها سحت، من السحت المحرم -نعوذ بالله جل وعلا- ولا حجة فيما تفعله الدولة .. ما هي معصومة الدولة، ليس كل ما فعلته يكون مباحًا، الدولة غير معصومة، وقد تفعل أشياء من أجل السياسة، ومن....تحتاط بها المسلمون، أو لأجل أسباب أخرى، فليست الدولة معصومة من كل شيء، ولكن على المؤمن أن يسأل أهل العلم، ويتبصر، ويفقه في دينه، ولا يحتج بالدولة، ولا بغير الدولة، العلم قال الله، قال رسوله، والحلال ما أحله الله ورسوله، والحرام ما حرمه الله ورسوله، لا ما حرمته الدولة، أو فلان، أو فلان. العلم علم الشريعة، وهي أحكام الله ورسوله، لا للناس، فالواجب على المؤمن أن يتقي الله، لو قالت الدولة: هاتوا ريالاً  ... راح عند المحكمة يطالب، أما في الغناء يقول: الدولة، يحتج بالهوى، لكن لو قالت الدولة: اترك أرضك، لا تأخذ هذه الأرض وإلا أعطنا مائة ريال كل شهر، قال: لا، ما أنا معطيكم، ولا بسامع، ولا مطيع، هذا الشرع، حكموا الشرع بيننا وبينكم، لهواه يطلب الشرع، ولهواه يستحل الحرام، نسأل الله السلامة.","link":"https://binbaz.org.sa/fatwas/2363/الرد-على-بعض-شبهات-المجيزين-لاستماع-الغناء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_897.mp3","categories":["الشعر والأغاني"]},{"id":7146,"question":"اختلفت أقوال العلماء في هذا البلد في حكم استماع الأناشيد الإسلامية، فمنهم من يقول بمنعها، وعدم استماعها؛ لأنها تشبه السماع الصوفي، ومنهم من يقول بجواز استماعها، وأنه لا بأس بذلك، فما وجه الحق والصواب في هذه المسألة؛ لأنها انتشرت عند الشباب المستقيم الصالح المهتدي؟ وكذلك التمثيليات، والمسرحيات الإسلامية هل هي جائزة، أم لا؟ نرجو إفادتنا، والتفضل بالحكم مع بيان الأدلة، وجزاكم الله خيرًا.","title":"التفصيل في حكم استماع الأناشيد الإسلامية","answer":"الجواب:\n\nالأناشيد الإسلامية مثل الأشعار، إن كانت سليمة؛ فهي سليمة، وإن كانت فيها منكر؛ فهي منكر، فالشعر من حيث هو مثلما قال النبي ﷺ: إن من الشعر لحكمة ولكن أكثر الشعراء مثلما قال الله: وَالشُّعَرَاءُ يَتَّبِعُهُمُ الْغَاوُونَ [الشعراء:224] فالشعر فيه الطيب، والخبيث مثل بقية الكلام حسنه حسن، وسيئه سيئ، فإذا كانت القصيدة سليمة في مدح الأخلاق الفاضلة والتحذير من الأخلاق الذميمة بالعقيدة الصحيحة، وذم العقيدة السيئة، وبيان بطلانها في أشباه ذلك، مما هو معروف في الشرع، فهي قصيدة طيبة.\n\nوهكذا الأناشيد إذا كانت الأناشيد فيها الدعوة إلى الخير، والتشجيع على الخير، والالتزام بالإسلام، وحماية الأوطان من شر الأعداء، ونحو ذلك؛ فلا بأس بها، وإن كانت الأناشيد فيها دعوة إلى الباطل، أو تحبيذ الباطل، أو تحبيذ الأخلاق الرذيلة؛ منعت، مثل بقية الشعر الممنوع. \n\nفالحاصل: أن البت فيها مطلقًا ليس بسديد، ينظر فيها، فالأناشيد السليمة لا بأس بها، والأناشيد التي فيها منكر، أو دعوة إلى منكر منكرة، ولا يمكن البت فيها إلا بعد عرضها، كل الأناشيد تعرض على أهل العلم، ويبين حكمها.","link":"https://binbaz.org.sa/fatwas/3192/التفصيل-في-حكم-استماع-الاناشيد-الاسلامية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1550.mp3","categories":["الشعر والأغاني"]},{"id":7191,"question":"كثر الكلام حول موضوع الأناشيد الإسلامية، والناس في حيرة حول هذا، وجاءت أسئلة بخصوص هذا الموضوع أكثر من سؤال، فنرجو من سماحتكم بيان ذلك، وتوضيحه؟","title":"حكم الاستماع للأناشيد الإسلامية","answer":"الجواب:\n\nالأناشيد الإسلامية فيها تفصيل، لا يمكن الجواب عنها مطلقًا، لا بد يكون فيها تفصيل، فكل شعر، أو أنشودة، سواء سمي أناشيد إسلامية، أو غير ذلك، لا بد يكون سليمًا مما يخالف الشرع المطهر، فإذا كانت سليمة مما يخالف الشرع المطهر في مدح الدين، مدح الأخلاق، مدح الكرم، والجود، الحث على الجهاد في سبيل الله، الحث على حماية الأوطان من الأعداء، الحث على الإخلاص لله في العمل، الحث على بر الوالدين على إكرام الجار، على غير هذا من الشؤون الإسلامية، بأساليب واضحة، ليس فيها ما يخالف الشرع المطهر، فليس فيها بأس، مثل ما قال الشافعي -رحمه الله- في الشعر: هو كالنثر حسنه حسن وقبيحه قبيح.\n\nوقال النبي ﷺ: إن من الشعر حكمة والله قال: وَالشُّعَرَاءُ يَتَّبِعُهُمُ الْغَاوُونَ ۝ أَلَمْ تَرَ أَنَّهُمْ فِي كُلِّ وَادٍ يَهِيمُونَ ۝ وَأَنَّهُمْ يَقُولُونَ مَا لَا يَفْعَلُونَ ۝ إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَذَكَرُوا اللَّهَ كَثِيرًا [الشعراء:224-227] الآيات، فهؤلاء مستثنون إن كان شعرهم سليمًا داخلاً في العمل الصالح، فهو مستثنى، ومن كان شعره ليس داخلاً في ذلك، بأن يدعو إلى ما يخالف الشرع؛ فإنه لا يكون شعره طيبًا، ولا ينبغي أن يسمح له، بل ينبغي أن يترك حتى يكون شعره موافقًا لشرع الله، سليمًا مما يخالفه. \n\nفكل أنشودة، أو أناشيد ينبغي أن تعرض على أهل العلم، على لجنة من أهل العلم، ينظرونها، وينقحونها، فإذا نقحوها، وبينوا أنها جائزة؛ تقدم في المدرسة، أو غير المدرسة، ولا تقبل من كل أحد هذه الأناشيد، بل ينظر فيها من لجنة إن كانت من جهة المعارف من جهة المعارف، إن كانت من جهة المعاهد من جهة المعاهد، من أي جهة تكون هذه الأناشيد، لا يسمح بها حتى تعرض على لجنة من أهل العلم والبصيرة المعروفين بالاستقامة والعلم بالشرع؛ حتى ينظروا فيها؛ لأن التساهل فيها قد يفضي إلى شر كثير، فلابد أن تعرض على أهل العلم الذين يعرف فيهم العلم والفضل والغيرة الإسلامية، فينظرون فيها، ويبينون ما فيها من خلل، ثم يوجهون أهل الأناشيد إلى ما هو الأفضل.\n\nالسؤال: طبعًا من رأي سماحتكم ألا تطرأ هذه الأناشيد على الانصراف عن سماع القرآن الكريم؛ لأن بعض الإخوة يشتكي بأنها صرفتهم عن سماع القرآن والذكر هذه الأناشيد؟\n\nالجواب: لا بد يكون لها وقت خاص قليل، ما تشغلهم عما هو أهم، لا عن دروسهم، ولا عن القرآن، ولا عن الذكر، يكون لها وقت قليل إذا أريدت، يكون لها وقت، إما قبل الدروس، أو بعد الدروس، أو في أثناء الدرس، إذا كان فيها فائدة تتعلق بالمصلحة الإسلامية على ما يوجه اللجنة -لجنة العلماء- على توجيه اللجنة التي تختص بهذا الشيء، وتنظر فيه، إما أن تفعل أو لا تفعل، أو في وقت كذا، أو في خمس دقائق، أو في عشر دقائق، أو في أقل، أو في أكثر، على.. إذا كانت إسلامية فهي إسلامية، وإن كانت ما هي إسلامية مباحة فهي مباحة على حسب قد تكون .. شيطانية.\n\nالسؤال: لكن يا شيخ بالنسبة للتسجيلات الإسلامية -جزاهم الله خيرًا- عندهم الكثير منها، وخالية من الموسيقى، أو في بعض منها شيء مختلط بالموسيقى، والموسيقى حرام؟\n\nالجواب: ما أدري والله، أنا ما عندي خبر عن هذا، لكن القاعدة موافقة الشرع ومخالفته، فالتي فيها موسيقى تمنع.","link":"https://binbaz.org.sa/fatwas/3235/حكم-الاستماع-للاناشيد-الاسلامية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1577.mp3","categories":["الشعر والأغاني"]},{"id":7207,"question":"بيني وبين أخي خصام حول إحضار القينات المغنيات في زواج لنا، وحجته أن هذا من باب إعلان الزواج، مع العلم أنه بعيد عن السنة، وتعلمون سماحتكم ما يرافق هذه القينات من الغناء الفاحش والاختلاط والتصوير وغيره، نرجو بيان وجه الحق والفصل بيننا، وجزاكم الله خير الجزاء؟","title":"حكم إحضار المغنيات بحجة إعلان النكاح","answer":"الجواب:\n\nالمشروع في الزواج إعلانه وإظهاره، وأن يكون فيه إعلان يجتمع النساء مع النساء والرجال مع الرجال؛ لأن الرسول ﷺ أمر بإعلان النكاح، وكان يفعل في عهد النبي ﷺ يجتمع النساء إلى أهل العروس، ويزفونها إلى زوجها، ويكون بينهم بعض الأغاني العادية، الوطنية، في مدح الزوج، ومدح أهل الزوج، أو مدح الزوجة، وأهلها، وما أشبه ذلك.\n\n\n\t\n\t\t\n\t\t\tأتيناكم أتيناكم \n\t\t\t فحينونا نحييكم\n\t\t\n\t\n\n\nإلى غير ذلك، هذا شيء لا بأس، أما الأغاني المنكرة التي فيها مدح الخمور، أو الدعوة إلى عشق النساء، أو عشق الرجال، أو رفع هذا بمكبرات الصوت، هذا كله منكر، أما الغناء العادي بين النساء وحدهن من دون اختلاط في محلهن، من دون مكبرات ولا اختلاط بين النساء، الغناء العادي لا بأس، هو من إعلان النكاح كما كان في عهد النبي ﷺ كما كان أزواج النبي يحضرنه -عليه الصلاة والسلام-.\n\nالسؤال: والرجال؟\n\nالجواب: وأما الرجال فلا، الرجال لا يجوز لهم أن يختلطوا مع النساء، أما لو كانوا وحدهم في السلاح، بالرمي، بالأشعار العربية التي ما فيها شر، ولا فيها طبول، ولا شيء؛ لا بأس، يكونون وحدهم بعيدين عن النساء كما يفعل بعض الناس، يرمون وقت الزواج لإعلان النكاح بالرمي، ويجتمعون على قصائد جيدة، فيها حماس، والدعوة إلى مكارم الأخلاق، ومحاسن الأعمال، والشجاعة، ويتعلمون الرمي بحمل السلاح، ما نعلم في هذا بأسًا. \n\nفقد فعل هذا الحبشة في مسجد النبي ﷺ كانوا يلعبون بالحراب في المسجد، والنبي ينظر إليهم، فهذا لا بأس به، كما أقره النبي ﷺ، إذا كان من هذا الطريق مما يتعلق بالحماس في تعلم الشؤون الحربية وكيف يحذف الرمح؟ وكيف يحمل الحربة؟ وكيف يرمي بالبندق؟ وكيف يحمل السيف؟ إلى غير ذلك، هذا شيء ينفع الجميع، أما مع اختلاط النساء فلا يجوز، أو مع الطبول كذلك، أو مع أغاني منكرة تتعلق بالنساء، أو شؤون النساء، أو جمال النساء، أو دعوة إلى فسوق وعصيان، أو خمور، أو أشياء هذا ينكر، يمنع.","link":"https://binbaz.org.sa/fatwas/3272/حكم-احضار-المغنيات-بحجة-اعلان-النكاح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1598.mp3","categories":["اللباس والزينة","الزفاف ووليمة العرس","الشعر والأغاني"]},{"id":7212,"question":"هل يجوز الرقص مع الدف للنساء؟","title":"حكم الرقص مع الدف للنساءوحكم رقص الرجال","answer":"الجواب:\n\nفيما بينهن لا بأس، الرقص بينهن لا بأس؛ لأنهن من شأنهن هذا، أما الرجال لا، لا يكن مع النساء. \n\nالسؤال: الرجال يرقصون؟\n\nالجواب: هذا ما يسمى رقصًا لعب لعب، .. مع الحراب، ومع الدرق، ما يسمى رقصًا.","link":"https://binbaz.org.sa/fatwas/3273/حكم-الرقص-مع-الدف-للنساء-وحكم-رقص-الرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1599.mp3","categories":["الشعر والأغاني"]},{"id":7324,"question":"شخص يسمع الأغاني، ويكتب كلمات الأغاني، يعني هو شاعر، ويهدي كلماته للمطربين، فما حكم كتابة هذا الشعر؟ وما حكم إعطاء هذه الكلمات للفنانين ليغنوها؟","title":"حكم استماع الأغاني وكتابة أشعارها","answer":"الجواب:  هو آثم، ومعين على الإثم، آثم ومعين على الإثم، والله يقول سبحانه: وَمِنَ النَّاسِ مَنْ يَشْتَرِي لَهْوَ الْحَدِيثِ لِيُضِلَّ عَنْ سَبِيلِ اللَّهِ بِغَيْرِ عِلْمٍ وَيَتَّخِذَهَا هُزُوًا أُولَئِكَ لَهُمْ عَذَابٌ مُهِينٌ  ۝  وَإِذَا تُتْلَى عَلَيْهِ آيَاتُنَا وَلَّى مُسْتَكْبِرًا كَأَنْ لَمْ يَسْمَعْهَا كَأَنَّ فِي أُذُنَيْهِ وَقْرًا فَبَشِّرْهُ بِعَذَابٍ أَلِيمٍ [لقمان:6-7] ولهو الحديث هو الغناء عند أكثر المفسرين، عند أكثر أهل العلم. ومعنى يشتري يعني يعتاض قد يأخذه بدون ثمن، وقد يأخذه بالثمن، قد يشتري الأغاني بالثمن، وقد يأخذها بدون ثمن.  لِيُضِلَّ عَنْ سَبِيلِ اللَّهِ قرئ بفتح الياء وضمها لِيُضِلَّ بأسباب أعماله ولِيَضِلَّ هو بسبب تعاطيه هذا المنكر بِغَيْرِ عِلْمٍ يضل غيره، ويضل هو بنفسه من غير شعور منه بما وقع فيه من البلاء، كثير من الناس قد يظن أنه مصيب، أو يظن أنه لا شيء عليه، وهو ضال مضل، ولا يدري.  ثم هذا البلاء وهو الاستماع للأغاني، والتلذذ بها يجره بعد ذلك إلى الاستهزاء بآيات الله، والتكبر عن سماعها، من اعتاد الأغاني، ومحبتها، ثقل عليه سماع القرآن والتلذذ بالقرآن، وربما استهزأ به أيضًا، واستكبر عن سماعه والعمل به، ولهذا جاء عن عبدالله بن مسعود  -وهو من كبار الصحابة وعلمائهم- كان يحلف في هذه الآية ويقول: والله إن الغناء لهو الحديث، ويقول: إنه ينبت النفاق في القلب كما ينبت الماء الزرع، ما معنى ذلك؟ معناه: إذا اعتاد الغناء؛ ثقل عليه سماع الخير والرغبة في الخير، ومجالسة أهل الخير، فنبت في قلبه النفاق؛ لأن النفاق كراهة الخير، وحب الشر، والتظاهر بالخير، وهو يكذب ليس من أهل الخير، كما قال -جل وعلا-: إِنَّ الْمُنَافِقِينَ يُخَادِعُونَ اللَّهَ وَهُوَ خَادِعُهُمْ وَإِذَا قَامُوا إِلَى الصَّلَاةِ قَامُوا كُسَالَى يُرَاءُونَ النَّاسَ وَلَا يَذْكُرُونَ اللَّهَ إِلَّا قَلِيلًا [النساء:142] هذه من علاماتهم التكاسل والتثاقل عن الصلاة، والرياء، يراؤون، يتظاهرون بأنهم مسلمون، وأنهم طيبون، وليسوا كذلك، ومن صفاتهم الغفلة وقلة الذكر. فهذا البلاء وهو الغناء والتلذذ بالغناء وتعاطيه واستعماله وبيعه وشراؤه من أسباب مرض القلوب، واستحسانها الباطل وتثاقلها عن الخير، وانصرافها إلى اللهو، والمجون بدلًا من سماع آيات الله، ثم قد يفضي بها ذلك إلى الضلال والإضلال والاستهزاء بالقرآن والاستكبار عن سماعه وقراءته، ونحو ذلك، فإذا سمع القرآن؛ أعرض، وإذا سمع قرآن الشيطان؛ أقبل، ولا حول ولا قوة إلا بالله. السؤال: حتى الأغاني بدون موسيقى؟ الجواب: ولو ما فيها موسيقى، إذا كان فيها موسيقى؛ صار الشر أكثر والإثم أكبر، إذا معها ربابة، أو موسيقى، أو عود؛ صار الإثم أكثر.","link":"https://binbaz.org.sa/fatwas/3412/حكم-استماع-الاغاني-وكتابة-اشعارها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1724.mp3","categories":["الشعر والأغاني"]},{"id":7328,"question":"شخص يسمع الأغاني، ويكتب كلمات الأغاني، يعني هو شاعر، ويهدي كلماته للمطربين، فما حكم كتابة هذا الشعر؟ وما حكم إعطاء هذه الكلمات للفنانين ليغنوها؟","title":"حكم استماع الأغاني وكتابة أشعارها","answer":"الجواب:  هو آثم، ومعين على الإثم، آثم ومعين على الإثم، والله يقول سبحانه: وَمِنَ النَّاسِ مَنْ يَشْتَرِي لَهْوَ الْحَدِيثِ لِيُضِلَّ عَنْ سَبِيلِ اللَّهِ بِغَيْرِ عِلْمٍ وَيَتَّخِذَهَا هُزُوًا أُولَئِكَ لَهُمْ عَذَابٌ مُهِينٌ  ۝  وَإِذَا تُتْلَى عَلَيْهِ آيَاتُنَا وَلَّى مُسْتَكْبِرًا كَأَنْ لَمْ يَسْمَعْهَا كَأَنَّ فِي أُذُنَيْهِ وَقْرًا فَبَشِّرْهُ بِعَذَابٍ أَلِيمٍ [لقمان:6-7] ولهو الحديث هو الغناء عند أكثر المفسرين، عند أكثر أهل العلم. ومعنى يشتري يعني يعتاض قد يأخذه بدون ثمن، وقد يأخذه بالثمن، قد يشتري الأغاني بالثمن، وقد يأخذها بدون ثمن.  لِيُضِلَّ عَنْ سَبِيلِ اللَّهِ قرئ بفتح الياء وضمها لِيُضِلَّ بأسباب أعماله ولِيَضِلَّ هو بسبب تعاطيه هذا المنكر بِغَيْرِ عِلْمٍ يضل غيره، ويضل هو بنفسه من غير شعور منه بما وقع فيه من البلاء، كثير من الناس قد يظن أنه مصيب، أو يظن أنه لا شيء عليه، وهو ضال مضل، ولا يدري.  ثم هذا البلاء وهو الاستماع للأغاني، والتلذذ بها يجره بعد ذلك إلى الاستهزاء بآيات الله، والتكبر عن سماعها، من اعتاد الأغاني، ومحبتها، ثقل عليه سماع القرآن والتلذذ بالقرآن، وربما استهزأ به أيضًا، واستكبر عن سماعه والعمل به، ولهذا جاء عن عبدالله بن مسعود  -وهو من كبار الصحابة وعلمائهم- كان يحلف في هذه الآية ويقول: والله إن الغناء لهو الحديث، ويقول: إنه ينبت النفاق في القلب كما ينبت الماء الزرع، ما معنى ذلك؟ معناه: إذا اعتاد الغناء؛ ثقل عليه سماع الخير والرغبة في الخير، ومجالسة أهل الخير، فنبت في قلبه النفاق؛ لأن النفاق كراهة الخير، وحب الشر، والتظاهر بالخير، وهو يكذب ليس من أهل الخير، كما قال -جل وعلا-: إِنَّ الْمُنَافِقِينَ يُخَادِعُونَ اللَّهَ وَهُوَ خَادِعُهُمْ وَإِذَا قَامُوا إِلَى الصَّلَاةِ قَامُوا كُسَالَى يُرَاءُونَ النَّاسَ وَلَا يَذْكُرُونَ اللَّهَ إِلَّا قَلِيلًا [النساء:142] هذه من علاماتهم التكاسل والتثاقل عن الصلاة، والرياء، يراؤون، يتظاهرون بأنهم مسلمون، وأنهم طيبون، وليسوا كذلك، ومن صفاتهم الغفلة وقلة الذكر. فهذا البلاء وهو الغناء والتلذذ بالغناء وتعاطيه واستعماله وبيعه وشراؤه من أسباب مرض القلوب، واستحسانها الباطل وتثاقلها عن الخير، وانصرافها إلى اللهو، والمجون بدلًا من سماع آيات الله، ثم قد يفضي بها ذلك إلى الضلال والإضلال والاستهزاء بالقرآن والاستكبار عن سماعه وقراءته، ونحو ذلك، فإذا سمع القرآن؛ أعرض، وإذا سمع قرآن الشيطان؛ أقبل، ولا حول ولا قوة إلا بالله. السؤال: حتى الأغاني بدون موسيقى؟ الجواب: ولو ما فيها موسيقى، إذا كان فيها موسيقى؛ صار الشر أكثر والإثم أكبر، إذا معها ربابة، أو موسيقى، أو عود؛ صار الإثم أكثر.","link":"https://binbaz.org.sa/fatwas/3412/حكم-استماع-الاغاني-وكتابة-اشعارها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1724.mp3","categories":["الشعر والأغاني"]},{"id":7408,"question":"أحب أن أحيط سماحتكم أنه قد ظهر في المجتمع السعودي ظاهرة مخترعة وسيئة جدًا، ومنكر شنيع وفظيع، وهو ما يسمونه بالشرعة بمناسبات الزواج، حيث يأتون بالرجل المتزوج ويدخلونه على النساء بعد أن يغطون العروسة... أمام النساء، ويأتي الرجل ويكشف الشرعة؟","title":"حكم ما يسمى بالشرعة في مناسبات الزواج","answer":"الجواب: هذه معروفة، هذه نبهنا عليها، وكتب لوزير الداخلية في ذلك، وعمم بذلك -نسأل الله أن يهدي الجميع- لا شك أن هذا العمل سيئ؛ لأنه يدخل الرجل على النساء مكشوفات سافرات، وربما فعل مع زوجته شيئًًا لا يناسب بحضرتهن ورؤيتهن، هذا لا يجوز، قد نُبه على هذا - ونسأل الله أن يهدي الجميع-.","link":"https://binbaz.org.sa/fatwas/3498/حكم-ما-يسمى-بالشرعة-في-مناسبات-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1802.mp3","categories":["الشعر والأغاني","الزفاف ووليمة العرس"]},{"id":7422,"question":"أحب أن أحيط سماحتكم أنه قد ظهر في المجتمع السعودي ظاهرة مخترعة وسيئة جدًا، ومنكر شنيع وفظيع، وهو ما يسمونه بالشرعة بمناسبات الزواج، حيث يأتون بالرجل المتزوج ويدخلونه على النساء بعد أن يغطون العروسة... أمام النساء، ويأتي الرجل ويكشف الشرعة؟","title":"حكم ما يسمى بالشرعة في مناسبات الزواج","answer":"الجواب: هذه معروفة، هذه نبهنا عليها، وكتب لوزير الداخلية في ذلك، وعمم بذلك -نسأل الله أن يهدي الجميع- لا شك أن هذا العمل سيئ؛ لأنه يدخل الرجل على النساء مكشوفات سافرات، وربما فعل مع زوجته شيئًًا لا يناسب بحضرتهن ورؤيتهن، هذا لا يجوز، قد نُبه على هذا - ونسأل الله أن يهدي الجميع-.","link":"https://binbaz.org.sa/fatwas/3498/حكم-ما-يسمى-بالشرعة-في-مناسبات-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1802.mp3","categories":["الشعر والأغاني","الزفاف ووليمة العرس"]},{"id":7615,"question":"أحسنتم، أيضاً يقول في سؤاله الثاني: هل يجوز استعمال الدف في الحفلات الدينية أم يعتبر من الآلات الموسيقية المحرمة، أفيدونا جزاكم الله خيراً؟","title":"حكم ضرب الدف في الحفلات الدينية","answer":"الجواب: الدف إنما هو في حق النساء، هذا هو الذي يجوز في حق النساء في الأعراس ونحوها من أمور النساء، وأما الرجال فلا يجوز لهم لا الدف ولا الطبل ولا غير ذلك؛ لأنه من آلات الملاهي، وإنما يجوز اللعب بالحراب.. بالأسلحة.. بالرمي.. بالبنادق؛ لأنه تدرب على شئون الحرب، كما فعل الحبشة بين يدي النبي صلى الله عليه وسلم بالدرق والحراب في مسجده عليه الصلاة والسلام، هذا لا بأس به، أما اللعب بالدفوف والطبول والأغاني عليه، هذا لا يجوز، والله المستعان. نعم.","link":"https://binbaz.org.sa/fatwas/4668/حكم-ضرب-الدف-في-الحفلات-الدينية ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_023/02304.mp3","categories":["نصائح وتوجيهات","الشعر والأغاني"]},{"id":7803,"question":"سؤاله الثاني والأخير يقول فيه: إنني أرتاح عندما يرثى أو يغني جماعة ما بأحد الموتى وحيث أن الدين نهى عن ذلك ونهى عن البكاء على الميت ولكني أتأثر وأرتاح عندما يبكون جماعة أو يرثون أحد الموتى، فهل علي ذنب أو كفارة في ذلك أدامكم الله على طريق الحق؟","title":"حكم رثاء الموتى","answer":"الجواب: هذا فيه تفصيل: إذا كان الرثاء من باب ذكر محاسن الميت بما يشوق إلى التأسي به والاقتداء به في الأعمال الطيبة من الجود والكرم والجهاد في سبيل الله وإنكار المنكر والدعوة إلى الخير فذكر هذا في المراثي ينفع المسلمين ولا يضرهم ويرتاح له كل مؤمن، أما إذا كانت الرثاء تهيج المصائب بالمصائب وتدعو إلى النياحة وتحرك أحوال أقارب الميت حتى يشتغلوا بالنياحة والصياح فلا ينبغي ذكرها ولا ينبغي قراءتها عندهم؛ لأن هذا يسبب مشاكل ويفضي إلى محرمات فلا يفعل.\nأما الأغاني التي تتضمن دعوة إلى الفسوق والعصيان أو تتضمن دعوة إلى شرب الخمور أو إلى غير هذا من الفساد أو إلى التشويق إلى النساء بغير حق أو إلى الحب بغير حق أو ما أشبه ذلك فهذه يجب إنكارها ويجب الحذر منها؛ لأنها تفسد الأخلاق وتفسد القلوب، كما قال ابن مسعود : «الغناء ينبت النفاق في القلب كما ينبت الماء البقل » والله يقول سبحانه وهو أصدق القائلين: وَمِنَ النَّاسِ مَنْ يَشْتَرِي لَهْوَ الْحَدِيثِ لِيُضِلَّ عَنْ سَبِيلِ اللَّهِ [لقمان:6].\nأما الغناء الذي فيه الدعوة إلى الخير والأمر بالخير فينبغي أن يكون بألحان العرب فيكون بالأشعار العربية المعروفة والقصائد العربية فلا محذور فيه لكن بغير ألحان النساء وأشباه النساء، لا، يكون بألحان عربية بالشعر العربي كما كان حسان ينشد في عهد النبي ﷺ في الرد على المشركين.","link":"https://binbaz.org.sa/fatwas/5156/حكم-رثاء-الموتى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_050/05006.mp3","categories":["نصائح وتوجيهات","الشعر والأغاني"]},{"id":8206,"question":"الرسالة التالية باعثها أخونا عبد الله العنيزان من الجبيل، أخونا له عدد من الأسئلة من بينها سؤال يقول: ابنتي تذهب إلى الروضة، رياض الأطفال، ولكن من بين الأشياء التي يؤدونها بالروضة: أن المدرسة تفتح لهم المسجل، وتسمعهم الأناشيد الغير مبتذلة، مثلاً عن الأم والوطن وما شابه ذلك، ولكن تلك الأناشيد تكون مصحوبة بالموسيقى، فهل يجوز لي أن أدع ابنتي تذهب، وهل يكون علي ذنب إذا استمعت لمثل ذلك؟","title":"حكم الأناشيد المصحوبة بالموسيقى","answer":"الجواب: هذا غلط من المدرسة، أما سماع الطفلة للأناشيد السليمة فلا حرج في ذلك، وهكذا الطفل، وهكذا غيرهما، من الأناشيد التي ليس فيها محرم، إنما هي للتشجيع على الأخلاق الفاضلة، أو ما يتعلق بواجب الوطن عليهم، وواجب دولتهم ونحو ذلك.\nأما إصحابها بالموسيقى هذا غلط ولا يجوز، والواجب على القائم على الروضات منع ذلك، حتى لا يبقى هناك مانع من مجيء الأطفال إليهم، فعليك أنت وإخوانك أن تتصلوا بالمسئولين عن هذه الروضات حتى يمنعوا هذا الشيء ؛ لأن هذا لا حاجة إليه، ويربي الأطفال الصغار على حب الموسيقى والتلذذ بها واستماعها بعد ذلك، فالطفل على ما ربي عليه، فعليكم أن تتصلوا بالمسئولين في هذا عن المدارس حتى يمنعوا ذلك، وحتى تسلم هذه الروضات مما يخالف شرع الله . نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6016/حكم-الاناشيد-المصحوبة-بالموسيقى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_095/09502.mp3","categories":["نصائح وتوجيهات","الشعر والأغاني"]},{"id":8217,"question":"الرسالة التالية باعثها أخونا عبد الله العنيزان من الجبيل، أخونا له عدد من الأسئلة من بينها سؤال يقول: ابنتي تذهب إلى الروضة، رياض الأطفال، ولكن من بين الأشياء التي يؤدونها بالروضة: أن المدرسة تفتح لهم المسجل، وتسمعهم الأناشيد الغير مبتذلة، مثلاً عن الأم والوطن وما شابه ذلك، ولكن تلك الأناشيد تكون مصحوبة بالموسيقى، فهل يجوز لي أن أدع ابنتي تذهب، وهل يكون علي ذنب إذا استمعت لمثل ذلك؟","title":"حكم الأناشيد المصحوبة بالموسيقى","answer":"الجواب: هذا غلط من المدرسة، أما سماع الطفلة للأناشيد السليمة فلا حرج في ذلك، وهكذا الطفل، وهكذا غيرهما، من الأناشيد التي ليس فيها محرم، إنما هي للتشجيع على الأخلاق الفاضلة، أو ما يتعلق بواجب الوطن عليهم، وواجب دولتهم ونحو ذلك.\nأما إصحابها بالموسيقى هذا غلط ولا يجوز، والواجب على القائم على الروضات منع ذلك، حتى لا يبقى هناك مانع من مجيء الأطفال إليهم، فعليك أنت وإخوانك أن تتصلوا بالمسئولين عن هذه الروضات حتى يمنعوا هذا الشيء ؛ لأن هذا لا حاجة إليه، ويربي الأطفال الصغار على حب الموسيقى والتلذذ بها واستماعها بعد ذلك، فالطفل على ما ربي عليه، فعليكم أن تتصلوا بالمسئولين في هذا عن المدارس حتى يمنعوا ذلك، وحتى تسلم هذه الروضات مما يخالف شرع الله . نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6016/حكم-الاناشيد-المصحوبة-بالموسيقى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_095/09502.mp3","categories":["نصائح وتوجيهات","الشعر والأغاني"]},{"id":8298,"question":"سؤاله الأخير في رسالته يقول: مع حفظي لكتاب الله، ومواظبتي على الصلوات إلا أنني أميل إلى استماع المطربين والمغنين، فما الحكم في هذا، وكيف أتخلص من ذلك؟","title":"كيفية الابتعاد عن سماع الغناء","answer":"الجواب: عليك أن تجاهد نفسك وأن تعتاض عن ذلك بسماع القرآن الكريم، والإكثار من تلاوته والاشتغال بذكر الله  وبما ينفعك في أمر دينك ودنياك، أما سماع المطربين والمطربات فهو من وسائل الشر، من وسائل عمى القلوب، ومن وسائل قسوتها وانحرافها عن طريق الخير، فإياك وهذا العمل احذره غاية الحذر، وقد قال الله : وَمِنَ النَّاسِ مَنْ يَشْتَرِي لَهْوَ الْحَدِيثِ لِيُضِلَّ عَنْ سَبِيلِ اللَّهِ بِغَيْرِ عِلْمٍ [لقمان:6] فجعل لهو الحديث مضلاً عن سبيل الله، ولهو الحديث هو الغناء وآلات الملاهي كما قال جمهور أهل العلم في تفسير الآية.\nفالواجب عليك الحذر من هذا السبيل، وأن تعتاض عن هذا الشر بما شرع الله من الخير في استماع القرآن الكريم، وتدبر معانيه.. بالإكثار من تلاوته.. بالإكثار من ذكر الله.. في التحدث مع إخوانك فيما ينفعكم، والمذاكرة فيما ينفعكم.. في التحدث مع أهلك فيما ينفعكم.. في الاشتغال بشيء آخر من الأمور المباحة حتى تشتغل عما حرم الله بما أباح الله، رزق الله الجميع الهداية. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6114/كيفية-الابتعاد-عن-سماع-الغناء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_201/20104.mp3","categories":["الشعر والأغاني","نصائح وتوجيهات"]},{"id":8309,"question":"سؤاله الأخير في رسالته يقول: مع حفظي لكتاب الله، ومواظبتي على الصلوات إلا أنني أميل إلى استماع المطربين والمغنين، فما الحكم في هذا، وكيف أتخلص من ذلك؟","title":"كيفية الابتعاد عن سماع الغناء","answer":"الجواب: عليك أن تجاهد نفسك وأن تعتاض عن ذلك بسماع القرآن الكريم، والإكثار من تلاوته والاشتغال بذكر الله  وبما ينفعك في أمر دينك ودنياك، أما سماع المطربين والمطربات فهو من وسائل الشر، من وسائل عمى القلوب، ومن وسائل قسوتها وانحرافها عن طريق الخير، فإياك وهذا العمل احذره غاية الحذر، وقد قال الله : وَمِنَ النَّاسِ مَنْ يَشْتَرِي لَهْوَ الْحَدِيثِ لِيُضِلَّ عَنْ سَبِيلِ اللَّهِ بِغَيْرِ عِلْمٍ [لقمان:6] فجعل لهو الحديث مضلاً عن سبيل الله، ولهو الحديث هو الغناء وآلات الملاهي كما قال جمهور أهل العلم في تفسير الآية.\nفالواجب عليك الحذر من هذا السبيل، وأن تعتاض عن هذا الشر بما شرع الله من الخير في استماع القرآن الكريم، وتدبر معانيه.. بالإكثار من تلاوته.. بالإكثار من ذكر الله.. في التحدث مع إخوانك فيما ينفعكم، والمذاكرة فيما ينفعكم.. في التحدث مع أهلك فيما ينفعكم.. في الاشتغال بشيء آخر من الأمور المباحة حتى تشتغل عما حرم الله بما أباح الله، رزق الله الجميع الهداية. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6114/كيفية-الابتعاد-عن-سماع-الغناء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_201/20104.mp3","categories":["الشعر والأغاني","نصائح وتوجيهات"]},{"id":8352,"question":"هل يجوز الغناء أو سماعه في الأفراح وحفلات الزواج والأعياد؟","title":"حكم الغناء في الأفراح والأعياد","answer":"الجواب: نعم يجوز بين النساء الغناء في الأفراح والجواري في الأعياد، كما فعل ذلك في عهده ﷺ، فهذا خاص بالنساء، ولا يجوز فيه الاختلاط مع الرجال، ولا ينبغي فعله للرجال، ولا يجوز للرجال، ولكن هذا من شأن النساء في أفراح العرس بينهن، الأغاني الجارية بها العادة في مدح الأزواج ومدح أهل الزوج وأسرة الزوجة وأشباه ذلك، الأغاني التي ليس فيها مدح لمحرم، ولا تشجيع على محرم، ولا دعوة إلى باطل، إنما هي أغاني عادية، فيما بين النساء في مدح الزوج وأسرته أو الزوجة وأسرتها أو ما يتعلق بذلك، هذا هو الذي يجوز ، وهو الذي فعل في عهد النبي ﷺ، وفعله المسلمون في إعلان النكاح، وهكذا تفعله الجواري في الأعياد، الجواري الصغار في الأعياد كل هذا لا حرج فيه إن شاء الله. نعم.\nالمقدم: بارك الله فيكم، سواءً صحب ذلك شيئاً من الموسيقى أو .... ؟\nالشيخ: مع الدف فقط، أما الموسيقى أو العود أو نحو ذلك لا يجوز، إنما هو مع الدف وهو معروف عند النساء، وهو الطاب الذي له وجه واحد، يفعل في الأعراس فقط أو ما تفعله الجواري في العيد، كما فعله بعض الجواري في بيت النبي ﷺ في بيت عائشة . نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6201/حكم-الغناء-في-الافراح-والاعياد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_113/11309.mp3","categories":["الشعر والأغاني"]},{"id":8393,"question":"تقدم في أعداد سابقة بيان حكم الغناء واختلاف أقوال العلماء فيه، مع اتفاقهم على تحريم السماع المؤدي إلى الفتنة وإباحة الغناء في الأفراح والأعياد، أما ما سوى ذلك ففيه قولان: والراجح الجواز، بشرط عدم الاحتراف والإشراك واجتناب ما فيه إثارة في الشعر، أو الصوت، أو اللحن؟","title":"حكم الغناء وما يترتب على سماعه","answer":"","link":"https://binbaz.org.sa/fatwas/6259/حكم-الغناء-وما-يترتب-على-سماعه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_116/11612.mp3","categories":["الشعر والأغاني"]},{"id":8442,"question":"الأخ هارون أيضاً يقول: إن النساء هناك يستمعن إلى الأغاني، ويرجو من سماحة الشيخ النصيحة؟","title":"حكم الاستماع إلى الأغاني وآثار ذلك","answer":"الجواب: نصيحتي لجميع الرجال والنساء عدم استماع الأغاني؛ فالأغاني خطرها عظيم؛ وقد بلي الناس بها في الإذاعات وفي التلفاز وفي أشياء كثيرة من الأشرطة وهذا من البلاء.\nفالواجب على أهل الإسلام من الرجال والنساء أن يحذروا شرها، وأن يعتاضوا عنها بسماع ما ينفعهم من كلام الله عز وجل، ومن كلام رسوله عليه الصلاة والسلام، ومن كلام أهل العلم الموفقين في أحاديثهم الدينية وندواتهم ومقالاتهم، كل ذلك ينفعهم في الدنيا والآخرة.\nأما الأغاني فشرها عظيم، وربما سببت للمؤمن انحرافاً عن دينه، والمؤمنة كذلك، وربما أنبتت النفاق في القلب بكراهة الخير؛ لأن النفاق أصله كراهة الخير وحب الشر، إظهار الإسلام وإبطان سواه.\nفالنفاق خطره عظيم، والأغاني تدعو إليه، فإن من اعتادها ربما كره سماع القرآن، وسماع النصايح والأحاديث النافعة، وأحاديث الرسول عليه الصلاة والسلام؛ وربما جرته إلى حب الفحش، والفساد، واعتياد الفواحش والرغبة فيها، والتحدث مع أهلها، والميل إليهم. فالواجب على أهل الإيمان من الرجال والنساء الحذر من شرها، يقول الله عز وجل في كتابه العظيم: وَمِنَ النَّاسِ مَنْ يَشْتَرِي لَهْوَ الْحَدِيثِ لِيُضِلَّ عَنْ سَبِيلِ اللَّهِ بِغَيْرِ عِلْمٍ وَيَتَّخِذَهَا هُزُوًا أُولَئِكَ لَهُمْ عَذَابٌ مُهِينٌ ۝ وَإِذَا تُتْلَى عَلَيْهِ آيَاتُنَا وَلَّى مُسْتَكْبِرًا كَأَنْ لَمْ يَسْمَعْهَا كَأَنََّ فِي أُذُنَيْهِ وَقْرًا فَبَشِّرْهُ بِعَذَابٍ أَلِيمٍ [لقمان: 6 - 7].\nيقول علماء التفسير: إن لهو الحديث هو الغناء، ويلحق بذا كل صوت منكر، كالمزامير وآلات الملاهي، هكذا قال أكثر علماء التفسير رحمة الله عليهم.\nوقال عبد الله بن مسعود : هو والله الغناء -وكان يقسم على ذلك، ويقول: إن الغناء ينبت النفاق في القلب كما ينبت الماء البقل يعني: الزرع، ومعنى ذلك: أنه يسبب للإنسان كراهة الخير وحب الشر، كراهة الذكر والقرآن ونحو ذلك، وحب الأغاني والملاهي وأشباه ذلك، وهذا نوع من النفاق؛ لأن المنافق يتظاهر بالإسلام ويكرهه في الباطن، يتظاهر بأنه مؤمن وهو في الباطن ليس كذلك، يتظاهر بحب القرآن وهو في الباطن ليس كذلك؛ فالأغاني تدعو إلى ذلك، تدعو إلى كراهة سماع القرآن والاستماع له، وتدعو إلى كراهة سماع الذكر والدعوة إلى الله، ويدعو أهلها يعني: الغناء يدعو أهله إلى خلاف ذلك، إلى حب المجون وحب الباطل، وحب الكلام السيئ، وحب الكلام في الفحش والغناء والمحبة، ونحو ذلك مما يتسبب عن الغناء مما يجر إلى انحراف القلوب؛ ومحبتها لما حرم الله، وكراهتها لما شرع الله ، وهذا واضح ممن جرب ذلك، فإن من جرب ذلك وعرف ذلك يعلم هذا، وهكذا الذين عرفوا أصحاب الغناء، وعرفوا أحوالهم، يظهر عليهم من الانحراف والفساد؛ بسبب حبهم للغناء ما هو شر عظيم، وفساد كبير لمن اعتاد ذلك، ولا حول ولا قوة إلا بالله. نعم.","link":"https://binbaz.org.sa/fatwas/6326/حكم-الاستماع-الى-الاغاني-واثار-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_120/12007.mp3","categories":["نصائح وتوجيهات","الشعر والأغاني"]},{"id":8797,"question":"هذه رسالة بعثها مرسلها وبدأ بقوله: بسم الله الرحمن الرحيم، وصلى الله على سيدنا محمد وعلى آله وصحبه وسلم، والسلام عليكم ورحمة الله وبركاته، أما بعد: أرسل رسالتي أنا المرسل (أ . ب. ج) من القطر العراقي، من محافظة أربيل، أبعث بالتبريكات ومع كل احترامي لبرنامجكم الناجح الذي يذكرنا ويوعظنا بآيات الله وسنة رسوله صلى الله عليه وسلم، والتجنب عن كل أمر فاسق، والله ولي التوفيق، إني أحمل في رسالتي هذه مجموعةً من الأسئلة التي هي ليست لي وحدي وإنما معي أصحابي، ولكننا جمعناها في رسالة واحدة لتعم الفائدة، ونرجو أن تجيبوا عن الأسئلة بما يرضي الله ثم يرضينا؛ لأن فيه بعض الأسئلة التي تهم جميع شبابنا في العالم الإسلامي، السؤال الأول يقولون فيه: إننا نحب الاستماع إلى الأغاني والموسيقى بأنواعها، وفينا أيضاً من هو عازف، فأردنا معرفة الموقف من الإسلام في هذا الموضوع، فهل ذلك حرام أم ماذا أفيدونا أفادكم الله؟","title":"حكم استعمال الآلات الغناء والمعازف","answer":"الجواب: الاستماع للأغاني والمعازف والموسيقى من جملة الملاهي المحرمة، والواجب على المؤمن ألا يستمع إليها، وألا يكون عاملاً فيها ولا عازفا؛ لأن الرسول ﷺ بين لنا من أنه يأتي في آخر الزمان قوم يستحلون الحر والحرير والخمر والمعازف، والمعازف هي: آلات الملاهي والغناء بها كله يسمى عزف، فالغناء عزف، وآلات الملاهي تسمى معازف، والأصل في هذا الباب قوله : وَمِنَ النَّاسِ مَنْ يَشْتَرِي لَهْوَ الْحَدِيثِ لِيُضِلَّ عَنْ سَبِيلِ اللَّهِ [لقمان:6] قال أكثر أهل العلم: لهو الحديث: الأغاني، ويلحق بها كل صوت منكر من المزامير والموسيقى وغير هذا من أصوات الملاهي، وبين الله سبحانه وتعالى أن هذه الآلات وهذه المعازف تضل أهلها قال: لِيُضِلَّ عَنْ سَبِيلِ اللَّهِ [لقمان:6]، وفي القراءة الأخرى: لِيَضِلَّ عَنْ سَبِيل اللَّهِ ، فدل ذلك على أن شراءها يعني: اعتياضها واستعمالها، فقد يشتريها بالمال وقد لا يشتريها بالمال، وقد يختارها ويستعملها فيضل بها عن سبيل الله يعني: عن دينه، ويضل بها غيره، فالواجب تركها والحذر منها حفاظاً على دين المؤمن؛ وحفاظاً على قلبه من الزيغ والرين والانحراف عن الهدى، والله جل وعلا ذكر الآية ذماً لأهل هذا العمل قال: ومن الناس يعني: بعض الناس، فهذا سيق مساق الذم، وَمِنَ النَّاسِ مَنْ يَشْتَرِي يعني: يعتاض لهو الحديث، وعرفت من قول أكثر أهل العلم: أنه الغناء وآلات اللهو، لِيُضِلَّ عَنْ سَبِيلِ اللَّهِ بِغَيْرِ عِلْمٍ وَيَتَّخِذَهَا هُزُوًا أُولَئِكَ لَهُمْ عَذَابٌ مُهِينٌ ۝ وَإِذَا تُتْلَى عَلَيْهِ آيَاتُنَا وَلَّى مُسْتَكْبِرًا كَأَنْ لَمْ يَسْمَعْهَا كَأَنَّ فِي أُذُنَيْهِ وَقْرًا فَبَشِّرْهُ بِعَذَابٍ أَلِيمٍ [لقمان:6-7]، هذا يبين أن استعمال هذه الملاهي واستعمال الأغاني والموسيقى وغير ذلك من أنواع اللهو من أعظم الأسباب في الضلال والإضلال، واتخاذ آيات الله هزواً، ومن الأسباب أيضاً في استكباره عن اتباع الحق، وعدم انقياده وارتياحه لسماع آيات الله عز وجل، فاتضح من هذا أن المعازف بأنواعها من أسباب مرض القلوب، ومن أسباب الضلال عن سبيل الله، ومن أسباب الاستكبار عن الحق، وروى البخاري في صحيحه رحمه الله، عن أبي مالك أو أبي عامر الأشعري رضي الله تعالى عنهما، عن النبي ﷺ أنه قال: ليكونن من أمتي أقوام يستحلون الحر والحرير والخمر والمعازف فالحر: هو الفرج الحرام والزنا، والحرير: معروف وهو محرم على الرجال، والخمر: معروف وهو المسكر .. هو كل مسكر، وهو حرام على الرجال والنساء جميعاً، والمعازف: هذا كذلك حرام على الجميع على الرجال والنساء، وعرفت أن المعازف من الأغاني والملاهي وأنواع الطرب كلها من أسباب الضلال عن سبيل الله، ومن أسباب اتخاذ آيات الله هزواً، ومن أسباب مرض القلوب وانحرافها عن الهدى، والاستكبار عن سماع آيات الله عز وجل، فالواجب على المؤمن أن يحذر هذا الأمر، وأن يحذره غيره، وهذا واجب على الجميع على الرجال والنساء في كل مكان؛ حرصاً على صلاح القلوب وسلامتها واستقامتها؛ وحذراً من غضب الله؛ وحذراً مما تجر إليه الأغاني والملاهي من الضلال والإضلال، والزيغ عن الهدى ولا حول ولا قوة إلا بالله. نعم.","link":"https://binbaz.org.sa/fatwas/6949/حكم-استعمال-الالات-الغناء-والمعازف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_221/22102.mp3","categories":["الشعر والأغاني"]},{"id":8941,"question":"أختنا تسأل عن حكم سماع الأغاني الوطنية وأغاني الأطفال المصحوبة بالموسيقى؟","title":"حكم سماع الأغاني الوطنية وغيرها المصحوبة بالموسيقى","answer":"الجواب: سماع الأغاني من حيث هي التي تتعلق بذكر النساء والرجال ومحاسن الرجل ومحاسن المرأة وما يتعلق بإثارة الشهوات والغرائز الجنسية كل هذا محرم لا يجوز ولو كانت خالية من الموسيقى، فإن كان معها موسيقى صار التحريم أشد، أو معها عود أو كمان أو طبول كل هذا لا يجوز.\nوهكذا الأغاني التي تتعلق بالأطفال إذا كان معها الموسيقى لا تجوز، أما إذا كان أناشيد ليس فيها محذور تسلي الأطفال، وليس فيها محذور فلا بأس بذلك، أناشيد في مدح الوطن أو مدح أمه أو مدح أبيه أو أشياء تسلي ليس فيها محذور شرعًا فلا بأس بذلك، وهكذا الأشعار العربية التي فيها الحث على الجود والكرم والشجاعة والصدق والبر والصلة وأشباه ذلك كان النبي ﷺ يسمع من حسان ومن غيره الأشعار التي ينشدونها في مدح الإسلام والدعوة إليه وهجاء المشركين وذمهم كل هذا لا بأس به. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7099/حكم-سماع-الاغاني-الوطنية-وغيرها-المصحوبة-بالموسيقى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_172/17203.mp3","categories":["الشعر والأغاني"]},{"id":9154,"question":"وهذه رسالة وصلت إلى البرنامج من المستمع علي صالح حسين يبدأ رسالته بقوله: بسم الله الرحمن الرحيم، الحمد لله رب العالمين، والصلاة والسلام على أشرف الأنبياء والمرسلين سيدنا محمد وعلى آله وصحبه أجمعين. إخوة الإسلام! السلام عليكم ورحمة الله وبركاته إن هذا البرنامج -أي: برنامج نور على الدرب- حقاً يجعل المسلم متفقهاً في دينه، بل يجعله عالماً إذا صح القول، وإنني لأشكر جزيل الشكر إخوة الإسلام العلماء الأفاضل الذين فكروا في هذا البرنامج، ولا أنسى أن أشكرهم دائماً.أيها الإخوة! لي أسئلة واستفسارات وهي:أولاً: عن الموسيقى؛ قرأت عن الموسيقى كتاب الحلال والحرام في الإسلام للأستاذ يوسف واتضح لي من قراءتي هذه أن الموسيقى حلال، وسألت أحد المشايخ في منطقتي في أرتريا لأزداد علماً؟ فقال لي: لا بأس بها إذا استعملت في المناسبات وأناشيد إسلامية، وأيضاً سمعت من أحد الدعاة يحرمها حرماناً قاطعاً، والسؤال هنا: هل حرام إذا استعملها المسلم في أناشيد إسلامية وذلك في المناسبات فقط؟ إذا كان الجواب بنعم ما هو دليل الذين يحللون ذلك؟ وما هو موقف الإسلام منهم أفيدونا أفادكم الله؟","title":"حكم استعمال الموسيقى في الأناشيد الإسلامية","answer":"الجواب: الموسيقى وأشباهها من آلات الملاهي لا شك في تحريمها، وأنها من المعازف المحرمة، والدليل على هذا قوله جل وعلا وَمِنَ النَّاسِ مَنْ يَشْتَرِي لَهْوَ الْحَدِيثِ لِيُضِلَّ عَنْ سَبِيلِ اللَّهِ [لقمان:6] قال أكثر أهل التفسير: إنه الغناء، قال جماعة منهم: ويلحق بذلك كل آلة ملهاة من مزمار وعود وغير هذا، والموسيقى من أشد آلات الملاهي إطراباً وإشغالاً ولهواً، فهي فيما نعتقد محرمة لهذه الآية ولما ثبت عنه عليه الصلاة والسلام أنه قال: ليكونن من أمتي أقوام يستحلون الحر والحرير والخمر والمعازف رواه البخاري في الصحيح، فالحر: هو الزنا، والحرير معروف لا يجوز للرجال، والخمر معروف.. محرمة على الجميع وهو كل مسكر، والمعازف هي آلات اللهو والغناء عليه والعزف عليها، وما ذاك إلا لأنها تصد القلوب عن ذكر الله وتمرضها وهي تجرها إلى أنواع من الباطل، تشغلها عن ذكر الله وعن قراءة القرآن، فالذي نعتقده هو القول بتحريمها وسائر آلات اللهو والطرب، ومن قال بحلها فنعتقد أنه قد أخطأ والله يعفو عنه، نعتقد أنه قد غلط نسأل الله أن يعفو عنا وعنه وعن جميع المسلمين، والواجب على المسلم هو أن يتحرى الحق فيما يختلف عليه الناس فيه؛ لأن الله يقول سبحانه: فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ إِنْ كُنتُمْ تُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الآخِر [النساء:59]، فإذا رددنا هذا الأمر إلى الكتاب والسنة وجدنا الكتاب يحذر من اللهو وهي من آلات اللهو، ووجدنا السنة تحذر من المعازف وهي من المعازف، مع أنه ورد في الباب أشياء أخرى تؤيد ذلك، فينبغي للمؤمن أن يحذرها وأن لا يغتر بقول من أحلها، ونسأل الله أن يوفق المسلمين جميعاً وولاة أمرهم لكل ما فيه صلاح دينهم ودنياهم، وأن يوفق علماء المسلمين لإصابة الحق فيما يفتون به وفيما يأتون ويذرون، وأن يجعلهم هداة مهتدين، وأن يمنحهم وإيانا وسائر إخواننا صلاح النية في القول والعمل.","link":"https://binbaz.org.sa/fatwas/7317/حكم-استعمال-الموسيقى-في-الاناشيد-الاسلامية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_231/23108.mp3","categories":["الشعر والأغاني"]},{"id":9195,"question":"أخونا أيضًا يسأل عن الفيديو والسينما وما حكم ذلك، ويسأل عن الموسيقى سماحة الشيخ؟","title":"حكم استعمال الفيديو والسينما وسماع الموسيقى","answer":"الجواب: هذه الآلات الفيديو والسينما فيها خطر عظيم، ولكن إذا كان الفيديو لم يشتمل إلا على أشرطة سليمة ليس فيها محذور شرعًا، لا نساء عاريات ولا أغاني وملاهي ولا غير ذلك، إنما هي أشرطة سليمة تنفع العبد في دنياه وأخراه فلا بأس، وهكذا السينما لو وجد شيء سليم ليس فيه ما يخالف الشرع المطهر لم يكن فيها بأس، ولكن لما كان المعروف من الناس الآن أن السينما تجمع شرًا كثيرًا، وهكذا الفيديو في الغالب يسجل فيه الأغاني والملاهي والنساء الكاسيات العاريات وشبه ذلك حرم ذلك.\nفالحاصل: أنها حرمت لما فيها من الشر ولما يكون فيها من الشر ويعرض فيها من الباطل، فلو وجد فيديو سليم أو سينما سليمة ليس فيها ما يخالف الشرع المطهر لم تحرم، ولكن بسبب ما يقع فيها من الشرور والفساد والصور العارية والاجتماع على الأغاني والملاهي حرمت بسبب ذلك، وهكذا الموسيقى؛ لأنها من آلات الملاهي فلا يجوز تعاطيها. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7355/حكم-استعمال-الفيديو-والسينما-وسماع-الموسيقى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_181/18105.mp3","categories":["الصور والتصوير","الشعر والأغاني"]},{"id":9408,"question":"أنا مقبل على الزواج، ولكن يمنعني من ذلك أسلوب الزواج عندنا حيث أنه لابد أن تقام حفلة العرس لمدة يومين بما تحويه من غناء فاحش ورقص ولهو واختلاط بين الرجال والنساء، ولا شك أن هذا منافٍ للدين، وكل من أراد الزواج من الشباب لابد من فعل هذا وإلا سوف لن يجد من يرضى به، فماذا يجب علي أن أفعل في مثل هذا الحال؟ وما هو الحد المشروع من اللهو والغناء؟ وهل الضرب على الطبول مشروع؟ وهل يتحتم علي السفر إلى بلاد أخرى بحثًا عن زوجة صالحة وطريقة إسلامية في الزواج؟ صاحب هذا السؤال هو أخونا منذر (أ. أ) من ليبيا؟","title":"ما حكم المنكرات في حفلات الزواج؟","answer":"الجواب: لا ريب أن كثيرًا من الناس لا يتقيد بالمشروع في الزواج ولا في غيره، والواجب على المسلمين أن يتقيدوا بشرع الله في الزواج وفي غيره أينما كانوا، في المملكة العربية السعودية أو في ليبيا أو في المغرب الأقصى أو في الجزائر أو في تونس أو في أي مكان، الواجب على أهل الإسلام التقيد بالأمر الشرعي، وأن يتواصوا بذلك وأن يتعاونوا عليه، كما قال الله سبحانه: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى وَلا تَعَاوَنُوا عَلَى الإِثْمِ وَالْعُدْوَانِ [المائدة:2] ، وقال سبحانه: وَالْعَصْرِ ۝ إِنَّ الإِنسَانَ لَفِي خُسْرٍ ۝ إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ [العصر:1-3].\nفلابد من التواصي بالحق ولابد من التواصي بالصبر في أمر الزواج وغيره، وفي جميع الأمور التي تقع بين المسلمين، فيتعاونون في إقامة الصلاة في الجماعة، وفي أداء الزكاة، وفي صيام رمضان وحفظه عما حرم الله، وفي أداء الحج مع الاستطاعة، وفي بر الوالدين، وفي صلة الأرحام، وفي ترك الغيبة والنميمة وسائر المعاصي، وفي ترك الكذب وشهادة الزور، وفي ترك ظلم الناس في الأموال والأعراض والدماء إلى غير ذلك ، الواجب على أهل الإسلام أينما كانوا ذكورًا كانوا أو إناثًا أن يتقوا الله، وأن يتعاونوا على طاعة الله ورسوله، وأن يتعاونوا أيضًا على ترك ما حرم الله ورسوله، وبذلك تحصل لهم السعادة والنجاة في الدنيا والآخرة.\nومن هذا أمر الزواج، يجب أن يكون الزواج على الطريقة الشرعية ليس فيه تكلف ولا إسراف ولا تبذير، بل يجب القصد في كل شيء، وعدم التكلف حتى يكثر الزواج، وحتى يحصل عفة النساء والرجال جميعًا، فالشباب بحاجة إلى الزواج، والنساء كذلك في حاجة إلى الزواج.\nوالتكلف هو تعاطي ما حرم الله من المنكرات، كل هذا مما يسبب تعطيل النكاح، وبقاء الشباب والفتيات من دون زواج.\nفلا يجوز اختلاط الرجال بالنساء في الأعراس، ولا في غيرها، بل يجب أن يكون النساء في محل خاص على حدة، والرجال على حدة، وأن تكون الوليمة مقتصدة ليس فيها تكلف ولا شيء يشق على الزوج وآل الزوجة، بل يتحرون جميعًا الاقتصاد وما يكفي المدعوين، ويقتصدون أيضًا في الدعوة التي لا تشق عليهم.\nوهكذا يشرع لهم الاقتصاد في المهور وعدم التكلف، وأن يسهلوا في المهور حتى يحصل النكاح وحتى يكثر الزواج بين الناس.\nومن ذلك أيضًا: مسألة الطرب فلا بأس أن تتعاطى النساء الدف يعني: الطار المعروف وهو ذو الوجه الواحد، يضربه النساء بينهن بصفة خاصة في محل خاص ليس فيه اختلاط الرجال، ولا مانع من الأغاني العادية التي ليس فيها محذور شرعًا التي بين النساء في بيت الزوج أو الزوجة أو أهل الزوج أو أهل الزوجة ونحو ذلك، كما كان يفعل في عهد النبي ﷺ وعهد أصحابه، وكان نساء النبي ﷺ يحضرن الأعراس، ويحضرن الغناء العادي والاحتفال العادي، كل هذا لا بأس به.\nأما وجود المطربات والأصوات العالية بالمكبرات التي تشغل الناس وتؤذي الجيران والمارة، ويعلن فيها الأغاني المحرمة هذا لا يجوز.\nوهكذا السهر الذي يضيع على الناس صلاة الفجر ويسبب ترك الصلاة التي أوجب الله، فهذا كله لا يجوز.\nوهكذا إيجاد آلات الملاهي من العود وأشباهها من آلات اللهو والطبول كل هذا لا يجوز.\nإنما يباح الطار المعروف وهو الدف فقط للنساء بشرط أن يكون خاليًا ليس فيه ما يسبب الفتنة من حلقات مزعجة أو أشياء مزعجة، بل الدف العادي وهو الطار العادي المعروف تضربه المرأة وتغني الأغاني القليلة المعتادة بينهن نصف ساعة أو ساعة ونحو ذلك ثم ينصرفن في أول الليل، ولا يسهرن إلى آخر الليل أو إلى معظم الليل؛ لأن هذا يضر الجميع، ويسبب النوم عن الصلاة من الجميع.\nفالحاصل: أن الواجب على جميع المسلمين في كل مكان أن يتحروا في زواجهم ما شرع الله، وأن يبتعدوا عما حرم الله، وأن يتواصوا بعدم التكلف لا في المهور، ولا في الولائم، ولا في دعوة الناس الكثيرين الذين يسببون المشاكل، ولا في إيجاد المطربات من طريق مكبرات الصوت، ولا إيجاد آلات الملاهي غير مجرد الدف والأغاني العادية لوقت مناسب من الليل ينتهي من دون طول ومن دون مشقة ومن دون السهر أكثر الليل أو كل الليل، هذا الواجب على المسلمين، وهذا المشروع لهم، وبهذا يتيسر للمسلمين تزويج شبابهم وتزويج فتياتهم بالمهور المناسبة والكلف المناسبة من دون مشقة ولا حرج ولا تعاطٍ لما حرم الله.\nوالواجب على ولاة الأمور في كل بلد من الأمراء والحكام أن يعينوا الناس على الخير، وأن يمنعوهم من الشر، وأن يأخذوا على أيدي السفهاء حتى ... الأمور على الوجه الشرعي، هذا هو الواجب على أمير البلد وقاضي البلد وأعيان البلد أن يتعاونوا بينهم في هذا الشيء، حتى يلزموا الناس بالخير ويمنعوهم من الشر، ومتى أصلح الله الرؤساء تبعهم الناس، متى صلح الأمير والأعيان، وتدخلت المحكمة والقضاة حصل الخير الكثير وانتهى الناس عما يضرهم.\nومتى سكت هؤلاء وهؤلاء وهؤلاء زاد الشر، وكثر البلاء، وتعطل الشباب وتعطلت الفتيات وهذا شيء لا يرضاه الله ورسوله، ولا يرضاه أهل الإيمان والعلم، فنسأل الله للجميع الهداية والتوفيق.\nالمقدم: أخونا يسأل يقول: إذا لم يكن هناك سبيل إلى التغيير الذي تفضلتم وبينتم ما يجب أن يكون عليه، هل يلزم المسلم أن يبحث عن زوجة في مكان آخر وفي بلد آخر يتوفر فيه ذلك الجو؟\nالشيخ: نعم، ليس من اللازم أن يتزوج في بلده، لا مانع من أن ينتقل إلى بلد آخر في بلاده بشرط العناية بالمرأة الصالحة البعيدة عما حرم الله، وعن أسباب الفتنة، يتحرى يسأل عنها، فإذا وجدها حرص عليها، يقول النبي ﷺ: تنكح المرأة لأربع: لمالها، ولجمالها، ولحسبها، ولدينها ثم قال: فاظفر بذات الدين تربت يداك.\nفالزوج يسعى إلى ذات الدين ويحرص عليها، وإذا حصل مع ذلك جمال أو حسب أو مال فهذا أكثر وإلى خير، لكن لا تكون أكبر همته وأعظم قصده الجمال فربما أطغاها الجمال، وربما أفسدها عليه الجمال، ولكن يحرص على أولًا كونها ذات دين، على كونها ذات دين، ثم يبحث بعد ذلك عما يريد من جمال أو حسب أو غير ذلك، فإذا انضم هذا إلى هذا خير إلى خير، وإلا قدم ذات الدين وإن قل جمالها وإن قل مالها وإن عدم حسبها، فالمرأة بنفسها ودينها لا بحسبها وجمالها. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/7572/ما-حكم-المنكرات-في-حفلات-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_189/18904.mp3","categories":["الشعر والأغاني","قضايا المرأة","الزفاف ووليمة العرس"]},{"id":9441,"question":"الأخ السائل (ن. ع) من حمص من سوريا في الحقيقة رجل غيور جزاه الله خيراً، فهو ذكر هنا عدة قضايا تتعلق باختلاف الفتوى في أمور هامة، ويذكر أنها في قضية مثل قضية الموسيقى والغناء، ويذكر أن مجلة عربية تصدر في بلد عربي أفتت بأنه لا يفتي بتحريم الغناء أو الموسيقى إلا متزمت جهول، ثم يسوق أيضاً ألواناً في أعداد مختلفة من هذه المجلة تبيح السفور المحتشم، هكذا قالت هذه المجلة في غير تبرج أو خلاعة، وأن الإسلام لا يدعو إلى الحجاب المتزمت الذي نراه في الكثير من البلاد العربية والبلاد الإسلامية، ثم يسوق أيضاً قضية حول مسألة التصوير، وأن هذه المجلة تشكك في الحديث الذي ورد في صحيح البخاري وتدعي أنه مدسوس في كتب الحديث، وما شأن المصورين حتى يكون عذابهم يوم القيامة أشد من القتلة أو من الزناة أو اللصوص، وإذا كان التصوير حراماً فلماذا لم ينه القرآن عنه صراحةً إلى غير ذلك، ويقول الأخ السائل: لماذا يسمح لمثل هذه المجلات بالتطاول على الإسلام، ويسأل عن الحكم الشرعي الصريح في هذه القضايا الثلاث؟","title":"بيان القول في حكم: الموسيقى والسفور والتصوير","answer":"الجواب: هذه المجلة وأشباهها ينبغي أن تمنع، وينبغي أن يقضى عليها؛ لأن هؤلاء المتكلمين فيها بهذا الكلام ليس عندهم علم ولا بصيرة ولا أدب شرعي، حتى الأدب الشرعي ليس عندهم أدب شرعي، هذه المسائل بينها أهل العلم وأقاموا عليها الدليل، فلا وجه للاعتراض من جاهل مركب لا درى ولا درى أنه ما درى، هذا جهل مركب أو متعمد للباطل والفسق، فالموسيقى والأغاني أمرهما معلوم، فالموسيقى من آلات الملاهي كالعود والطنبور والغناء من أخبث الملاهي فكلاهما محرم، والشعر العربي لا يدخل في ذلك، الأشعار العربية بلحون العرب فيما أباح الله، كشعر حسان وكعب بن مالك وغيرهما ممن بعدهم من الشعراء، على الطريقة العربية فيما أحل الله لا بأس به، أما الأغاني من النساء أو من أشباه النساء بالألحان والتطريب، وذكر حالات النساء من جمال وحب وغرام، هذا محرم عند أهل العلم، بل حكاه بعضهم إجماعاً، ولم يخالف فيه إلا من لا يعتد بخلافه، فالموسيقى وآلات الملاهي من العود والطنبور والرباب كلها محرمة وكلها شر، وهكذا الأغاني من النساء وغير النساء فيما يتعلق بالحب والغرام وذكر صفات النساء وما يتعلق بهذه الأمور، أو مدح الخمر أو مدح ما حرم الله كله محرم.\nوهكذا مسألة السفور منكر وقد دلت الأدلة على منعه، ومن ذلك قوله : وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53].\nفربنا  يأمر بالحجاب ويخبرنا أنه أطهر لقلوب الجميع، ويقول سبحانه في كتابه العظيم: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ أَوْ أَبْنَائِهِنَّ [النور:31] إلى آخر الآية، فكيف يقال في هذا: أنه متزمت، وإنما هذا كلام إنسان لا يعقل، أو لا يستحي.\nفالحاصل: أن هذا منكر.. السفور منكر، لو قال: إن هناك بعض الأدلة تدل على إباحة السفور وترك القول بالتزمت لكان هذا من طريق أهل العلم، هناك من يقول بالسفور إذا كان لا يضر، أما سفور فيه الزينة والجمال وفيه وضع الأصباغ على الوجه ونحو ذلك فلا يبيحه أحد، بل هو منكر عند أهل العلم، وإنما أباح بعض الناس السفور الذي ليس معه زينة في الوجه لا كحل ولا أشياء من الزينة في الوجه، وهو قول ضعيف أيضاً ومرجوح، والصواب: أنه محرم، وأن الواجب الحجاب مطلقاً، ولو كانت لم تفعل شيئاً في الوجه من أنواع الزينة من أصباغ وكحل ونحو ذلك، فإن الوجه هو زينة المرأة وهو عنوانها، وقد كن يكشفن الوجه قبل الحجاب، فلما نزل الحجاب أمر الله النساء بالحجاب، وأمرهن النبي صلى الله عليه وسلم بالحجاب، وثبت في الصحيحين عن عائشة رضي الله عنها قالت: لما سمعت صوت صفوان -حين وجدها ليس عندها أحد- يقول: إنا لله وإنا إليه راجعون، قالت: فخمرت وجهي، وكان قد رآني قبل الحجاب فعرفني لما رآني، فلما سمعت صوته خمرت وجهي، فدل ذلك على أنهن قبل الحجاب يكشفن الوجه، وبعد الحجاب أمرن بستر الوجه مع عموم الآية التي تلونا سابقاً وهي قوله سبحانه: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ [الأحزاب:53]، ولم يقل: إلا الوجه، ثم قال: ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] ، وقال: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ [النور:31]، ولم يقل: إلا الوجه فلا بأس بإبدائه مطلقاً.\nفهذا الكلام الذي قاله صاحب المجلة كلام سقيم، كلام رديء لا ينبغي لعاقل أن يقوله.\nوأما التصوير فقد جاء فيه عدة أحاديث، ليست عند البخاري وحده، بل عند البخاري وعند مسلم وعند أهل السنن الأربعة، وعند الإمام أحمد في مسنده وعند مالك في موطئه، وعند الدارمي في سننه، رواها الأئمة بأسانيد صحيحة عن أبي هريرة وعن ابن عباس وعن عائشة وعن علي بن أبي طالب وعن جماعة آخرين، وعن أبي جحيفة كلها تدل على تحريم التصوير لذوات الأرواح، في الصحيحين من حديث عائشة ومن حديث ابن عباس: أشد الناس عذاباً يوم القيامة المصورون، وفي حديث عائشة أيضاً: إن أصحاب هذه الصور يعذبون يوم القيامة ويقال لهم: أحييوا ما خلقتم، وفي حديث أبي جحيفة يقول : إن الرسول ﷺ لعن آكل الربا وموكله ولعن المصور، ويقول في حديث علي: لا تدع صورة إلا طمستها ولا قبراً مشرفاً إلا سويته، ويقول في حديث ابن عباس: من صور صورة في الدنيا كلف أن ينفخ فيها الروح وليس بنافخ، ويقول في حديث ابن عباس أيضاً عند الصحيحين عند البخاري ومسلم: كل مصور في النار ، يجعل له بكل صورة صورها نفس يعذب بها في جهنم.\nوالعلة في هذا والحكمة في ذلك معلومة، فإن الصور من وسائل الشرك، من وسائل عبادة غير الله، وكان النصارى إذا مات فيهم الميت الصالح بنوا على قبره مسجداً، وصوروا فيه صورته كما قاله النبي ﷺ ، وكانوا يصورون عظماءهم وينصبونها في الطرقات وفي كنائسهم وفي بيعهم، فهذا من وسائل العبادة لغير الله سبحانه وتعالى، ثم إذا كان المصور امرأة أو أمرد كان أيضاً من وسائل الفاحشة، من وسائل الفتنة، فالتصوير فيه فتنة وفيه شر عظيم، فلهذا حرمه الله ، فلا يجوز لعاقل أو لمسلم أن يقول: لماذا أو لماذا أو يعترض على شرع الله سبحانه وتعالى، بل يجب التسليم والانقياد لشرع الله، والطاعة لأمر الله ورسوله.\nهذا هو الواجب على كل مسلم، لكن ذكر بعض العلماء أنه يجوز التصوير عند الضرورة التي تدعو لهذا، مثل ما قد يضطر الإنسان إلى أخذ الحفيظة -حفيظة النفوس- التي تسمى التابعية إذا كانت الدولة لا تسمح بإعطائه إياها إلا بصورة فيكون مضطراً في هذه الحالة، وقد قال الله سبحانه: وَقَدْ فَصَّلَ لَكُمْ مَا حَرَّمَ عَلَيْكُمْ إِلَّا مَا اضْطُرِرْتُمْ إِلَيْهِ [الأنعام:119] أو إعطاء رخصة القيادة للسيارات إذا لم يعط رخصة إلا بصورة في دولته فهو مضطر إلى هذا الشيء، والله يعلم من قلبه أنه يكره الصور، فإذا أخذ ذلك مع كراهته لذلك إنما هو لأجل الإكراه والضرورة فلا حرج عليه في ذلك.\nالمقصود أن الاعتراض على شرع الله أمر لا يجوز وأمر منكر، بل يجب التسليم لشرع الله والبحث عما أشكل على الإنسان، إذا أشكل عليه أن يبحث، يسأل أهل العلم: ما حكمة كذا.. ما دليل كذا، والله المستعان ولا حول ولا قوة إلا بالله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7606/بيان-القول-في-حكم-الموسيقى-والسفور-والتصوير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_239/23907.mp3","categories":["الصور والتصوير","الشعر والأغاني"]},{"id":9450,"question":"السؤال الثاني في رسالة الأخ آدم ، يقول فيه: بعض الناس يزعمون أنهم يمدحون الرسول ﷺ بالشعر والوصف الجميل، مع العلم بأنهم يتقاضوا أجرًا على ذلك، هل يجوز هذا المدح، أفيدونا أفادكم الله؟","title":"حكم إعطاء الشعراء المال على مدح الرسول","answer":"الجواب: إذا مدحوا الرسول ﷺ بما هو حق فنحسن الظن ونياتهم إلى الله، وإذا أكرمهم من مدحوا الرسول ﷺ عنده فلا بأس، قد كان النبي ﷺ يعطي المنح للوفود وللشعراء والجوائز وهم كفار فكيف بالمسلمين.\nفالمقصود أن المادح للرسول ﷺ بالحق كأن يمدحه بأنه حسن الخلق بين المسلمين، متواضعًا، وأنه بلغ الرسالة، وأدى الأمانة، وأن صفته كذا من توفير لحيته عليه الصلاة والسلام، ومن بشاشته للمسلمين، ومن نصحه لله ولعباده، ومن زهده في الدنيا ورغبته في الآخرة، ومن صبره على الجهاد وأذى الأعداء إلى غير هذا من أخلاقه العظيمة، هذا طيب ولا بأس أن يعطى من قال ذلك وأن يجاز إن كان وافدًا ويعطى على شعره ما يرجى فيه تشجيعه على الخير وترغيبه في الثبات على الإسلام ولا حرج في ذلك؛ لأن هذا فعل الأخيار ومنهم وعلى رأسهم رسول الله عليه الصلاة والسلام.\nأما النية فإلى الله، الله يعلم نياتهم. نعم.","link":"https://binbaz.org.sa/fatwas/7614/حكم-اعطاء-الشعراء-المال-على-مدح-الرسول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_191/19105.mp3","categories":["الشعر والأغاني"]},{"id":9454,"question":"السؤال الثاني في رسالة الأخ آدم ، يقول فيه: بعض الناس يزعمون أنهم يمدحون الرسول ﷺ بالشعر والوصف الجميل، مع العلم بأنهم يتقاضوا أجرًا على ذلك، هل يجوز هذا المدح، أفيدونا أفادكم الله؟","title":"حكم إعطاء الشعراء المال على مدح الرسول","answer":"الجواب: إذا مدحوا الرسول ﷺ بما هو حق فنحسن الظن ونياتهم إلى الله، وإذا أكرمهم من مدحوا الرسول ﷺ عنده فلا بأس، قد كان النبي ﷺ يعطي المنح للوفود وللشعراء والجوائز وهم كفار فكيف بالمسلمين.\nفالمقصود أن المادح للرسول ﷺ بالحق كأن يمدحه بأنه حسن الخلق بين المسلمين، متواضعًا، وأنه بلغ الرسالة، وأدى الأمانة، وأن صفته كذا من توفير لحيته عليه الصلاة والسلام، ومن بشاشته للمسلمين، ومن نصحه لله ولعباده، ومن زهده في الدنيا ورغبته في الآخرة، ومن صبره على الجهاد وأذى الأعداء إلى غير هذا من أخلاقه العظيمة، هذا طيب ولا بأس أن يعطى من قال ذلك وأن يجاز إن كان وافدًا ويعطى على شعره ما يرجى فيه تشجيعه على الخير وترغيبه في الثبات على الإسلام ولا حرج في ذلك؛ لأن هذا فعل الأخيار ومنهم وعلى رأسهم رسول الله عليه الصلاة والسلام.\nأما النية فإلى الله، الله يعلم نياتهم. نعم.","link":"https://binbaz.org.sa/fatwas/7614/حكم-اعطاء-الشعراء-المال-على-مدح-الرسول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_191/19105.mp3","categories":["الشعر والأغاني"]},{"id":9469,"question":"السؤال الثاني في رسالة الأخ: شيخي محمد بلدية يقول فيه: هل الاستماع إلى الأغاني حرام، أفيدونا أفادكم الله؟","title":"حكم استماع الأغاني","answer":"الجواب: الاستماع إلى الأغاني لاشك في حرمته؛ وما ذاك إلا لأنه يجر إلى معاصٍ كثيرة وإلى فتن متعددة، ويجر إلى العشق، والوقوع في الزنا والفواحش واللواط، ويجر أيضًا إلى معاصٍ أخرى من شرب المسكرات ولعب القمار وخلطة الأشرار، وربما أوقع في الشرك والكفر بالله، على حسب أحوال الغناء واختلاف أنواعه.\nوالله جل وعلا يقول في كتابه العظيم: وَمِنَ النَّاسِ مَنْ يَشْتَرِي لَهْوَ الْحَدِيثِ لِيُضِلَّ عَنْ سَبِيلِ اللَّهِ بِغَيْرِ عِلْمٍ وَيَتَّخِذَهَا هُزُوًا أُولَئِكَ لَهُمْ عَذَابٌ مُهِينٌ ۝ وَإِذَا تُتْلَى عَلَيْهِ آيَاتُنَا وَلَّى مُسْتَكْبِرًا كَأَنْ لَمْ يَسْمَعْهَا كَأَنَّ فِي أُذُنَيْهِ وَقْرًا فَبَشِّرْهُ بِعَذَابٍ أَلِيمٍ [لقمان:6-7]، فأخبر سبحانه أن بعض الناس يشتري لهو الحديث ليضل عن سبيل الله، قرئ: ليضل وقرئ: ليضل واللام للتعليل.\nوالمعنى أنه بتعاطيه قد ........ لهو الحديث وهو الغناء يجره ذلك إلى أن يضل ويضل غيره، يضل بسبب ما يقع في قلبه من القسوة والمرض فيضل عن الحق بتساهله بمعاصي الله وركوبه لها وتركه بعض ما أوجب الله، ترك الصلاة في جماعة من ترك بر الوالدين، من لعب القمار، من ميله إلى الزنا والفواحش واللواط.. إلى غير هذا مما قد يقع بسبب الأغاني.\nقال أكثر المفسرين: معنى لَهْوَ الْحَدِيثِ في الآية معناه: الغناء، وقال جماعة آخرون: يضاف إلى ذلك كل صوت ينكر من أصوات الملاهي داخل في ذلك كالمزمار والعود والكمان وأشباه ذلك.\nوهذا كله يصد عن سبيل الله، ويسبب الضلال والإضلال، وثبت عن عبد الله بن مسعود  الصحابي الجليل أحد علماء الصحابة  أنه قال في الآية: «إنها والله الغناء » وقال: «إنه ينبت النفاق في القلب كما ينبت الماء البقل » والآية تدل على هذا المعنى، فإن الله قال: لِيُضِلَّ عَنْ سَبِيلِ اللَّهِ بِغَيْرِ عِلْمٍ [لقمان:6] يعني يعمى عليه الطريق كالسكران يعمى عليه الطريق؛ لأن الغناء يسكر القلوب، ويوقع في الهوى والباطل فيعمى عن الصواب إذا اعتاد ذلك حتى يقع في الباطل من غير شعور بسبب شغله بالغناء وامتلاء قلبه به، وميله إلى الباطل وإلى است فلانة وفلان وإلى صحبة فلان وفلانة وصداقة فلان وفلانة وغير ذلك.\nوَيَتَّخِذَهَا هُزُوًا [لقمان:6] يعني يفضي إلى اتخاذ سبيل الله هزوًا، إلى اتخاذ دين الله سبيل الله هو دينه، فالغناء واللهو يفضي إلى اتخاذ طريق اللهو هزوًا ولعبًا وعدم المبالاة في ذلك.\nوإذا تلي عليه القرآن استكبر وثقل عليه؛ لأنه اعتاد سماع الغناء وآلات الملاهي فهو يثقل عليه سماع القرآن ولا يستريح لسماع القرآن، وهذه من العقوبات العاجلة.\nفالواجب على المؤمن أن يحذر ذلك، وهكذا على كل مؤمنة الحذر من ذلك ، وجاء في المعنى أحاديث كثيرة كلها تدل على تحريم الغناء وآلات اللهو والطرب وأنها وسيلة إلى شر كبير، والله المستعان .نعم.","link":"https://binbaz.org.sa/fatwas/7634/حكم-استماع-الاغاني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_192/19202.mp3","categories":["الشعر والأغاني"]},{"id":9597,"question":"السؤال الثالث في رسالة الإخوة السودانيين: نرجو منكم توضيح الآيات أو الأحاديث التي تحرم الغناء أفيدونا أفادكم الله؟","title":"أدلة تحريم الغناء","answer":"الجواب: نعم، يقول الله جل وعلا في كتابه المبين: وَمِنَ النَّاسِ مَنْ يَشْتَرِي لَهْوَ الْحَدِيثِ لِيُضِلَّ عَنْ سَبِيلِ اللَّهِ بِغَيْرِ عِلْمٍ وَيَتَّخِذَهَا هُزُوًا أُولَئِكَ لَهُمْ عَذَابٌ مُهِينٌ ۝ وَإِذَا تُتْلَى عَلَيْهِ آيَاتُنَا وَلَّى مُسْتَكْبِرًا كَأَنْ لَمْ يَسْمَعْهَا كَأَنَّ فِي أُذُنَيْهِ وَقْرًا فَبَشِّرْهُ بِعَذَابٍ أَلِيمٍ [لقمان:6-7].\nقال أكثر أهل العلم: إن المراد بـ(لهو الحديث) الغناء فهو لهو الحديث.\nوقال بعضهم إضافة إلى ذلك: أيضًا أصوات المزامير و الملاهي ....... .......... هذا هو لهو الحديث و..... وهو من أسباب الضلالة عن سبيل الله والإضلال، فإن القلوب إذا تشبعت بالأغاني مرضت وقست وانحرفت فوقعت في الضلال والإضلال وثقل عليها سماع القرآن واستكبرت عن سماعه فهو يفضي بأهله إلى فساد القلوب وانحرافها وتثاقلها عن سماع القرآن وأنسها بالغناء .... من الكلام حتى قال عبد الله بن مسعود : «إن الغناء ينبت النفاق في القلب كما ينبت الماء الزرع » فهذا يبين لنا خطر الأغاني وشرها وآلات الملاهي.\nوقد جاء في المعنى أحاديث تدل على تحريم الأغاني والملاهي ومن ذلك ما رواه البخاري في الصحيح عن النبي ﷺ أنه قال: ليكونن من أمتي أقوام يستحلون الحر والحرير والخمر والمعازف.\nالحر: هو الفرج الحرام الزنا، الحرير معروف وهو محرم على الرجال، والخمر معروف وهو كل مسكر، والمعازف: الأغاني والملاهي فأخبر النبي ﷺ أنه يأتي في آخر الزمان قوم يستحلونها وهي محرمة لضعف إيمانهم وقلة مبالاتهم، ولا حول ولا قوة إلا بالله. نعم.","link":"https://binbaz.org.sa/fatwas/7763/ادلة-تحريم-الغناء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_193/19307.mp3","categories":["الشعر والأغاني"]},{"id":9642,"question":"السؤال الثالث في رسالة الأخ (ح. ع. س) من الأردن يقول فيه: هل سماع ومشاهدة الأغاني من الراديو أو التلفزيون حرام في الإسلام في بعض الأوقات من ليل أو نهار أفيدونا أفادكم الله؟","title":"حكم سماع الأغاني","answer":"الجواب: نعم، سماع الأغاني والملاهي حرام في الإسلام، كما قال الله : وَمِنَ النَّاسِ مَنْ يَشْتَرِي لَهْوَ الْحَدِيثِ لِيُضِلَّ عَنْ سَبِيلِ اللَّهِ [لقمان:6] و(لهو الحديث) قال أكثر العلماء: إنه الغناء، ويضاف إليه أيضًا أصوات الملاهي كالطنبور والعود والكمان وشبه ذلك، فهي كلها تصد عن سبيل الله وتقسي القلوب وتمرضها.\nوأخبر الرب  أن ذلك من أسباب الضلال والإضلال من أسباب استكبار العبد عن سماع كتاب الله، والقلب إذا أمر بالأغاني وكثر سماعه لها فإنها تصده عن الحق وتسبب له أمراضًا خطيرة وتثاقل عن طاعة الله ورسوله وعن سماع القرآن والمواعظ حتى قال عبد الله بن مسعود : «إنه ينبت النفاق في القلب كما ينبت الماء الزرع».\nوقال النبي ﷺ: ليكونن من أمتي أقوام يستحلون الحر والحرير والخمر والمعازف أخبر أنه يكون في آخر الزمن قوم يستحلون المعازف وهي محرمة، والمعازف: الأغاني وآلات اللهو، والله المستعان. نعم.","link":"https://binbaz.org.sa/fatwas/7808/حكم-سماع-الاغاني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_194/19405.mp3","categories":["الشعر والأغاني"]},{"id":9670,"question":"السؤال السادس في رسالة الأخت إستبرق تقول فيه: أنا أقوم بواجباتي الدينية من الصلاة والصوم وقراءة القرآن بكل إخلاص، ومع ذلك أستمع للأغاني العاطفية والخالية من ذكر الخمر وما شابه ذلك من المحرمات، هل يصح لي ذلك أفيدونا أفادكم الله؟","title":"حكم سماع المرأة المتدينة للأغاني","answer":"الجواب: ثبتك الله على الخير، ونسأل الله لك المزيد من الخير لكن ننصحك بأن لا تسمعي الأغاني مطلقًا؛ لأنها شر ولأنها تفضي إلى فساد كبير في القلوب، ونوصيك بسماع إذاعة القرآن فإن فيها الخير العظيم وسماع نور على الدرب وسماع الأحاديث النافعة المفيدة، أما سماع الأغاني فاتركيها واحذريها؛ لأن شرها كبير، وقد قال الله سبحانه: وَمِنَ النَّاسِ مَنْ يَشْتَرِي لَهْوَ الْحَدِيثِ لِيُضِلَّ عَنْ سَبِيلِ اللَّهِ [لقمان:6] قال أكثر أهل العلم: إن لهو الحديث هو الغناء، وقال عبد الله بن مسعود : «إن الغناء ينبت النفاق في القلب كما ينبت الماء البقل » وعبد الله بن مسعود هذا من أصحاب النبي ﷺ ومن علمائهم ، والنبي عليه الصلاة والسلام يقول: ليكونن من أمتي أقوام يستحلون الحر والحرير والخمر والمعازف.\nفأخبر أنه يكون في آخر الزمان قوم يستحلون المعازف وهي الملاهي والأغاني، نسأل الله أن يحمينا وإياك من ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/7836/حكم-سماع-المراة-المتدينة-للاغاني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_194/19418.mp3","categories":["الشعر والأغاني"]},{"id":10077,"question":"هل في سماع الأغاني والأشعار إثم على سامعها؟ وما الدليل القاطع على ذلك؟","title":"حكم سماع الشعر والأغاني","answer":"الجواب: الأشعار باللغة العربية أو بأي لغة إذا كانت في الخير والدعوة إلى الخير والثناء على أهل الإيمان وبيان أحكام الإسلام أو بيان التحذير من المعاصي أو ما أشبه ذلك إذا كانت في خير فلا بأس، سواء كان باللغة العربية أو بغيرها من دون آلات اللهو، لا يكون معها آلات اللهو لا موسيقى ولا طبل ولا عود ولا كمان ولا غير هذا من آلات اللهو فلا بأس، أما الأغاني كونها بصيغة الأغاني أغاني النساء وأغاني المتشبهين بالنساء فهذه عند أكثر أهل العلم ممنوعة لا تجوز، ذهب أكثر أهل العلم لمنعها لأنها تجر إلى الشر بالأصوات التي يأتي بها النساء أو المتشبهين بالنساء، تجر إلى الفتنة وربما جرت إلى الميل إلى النساء أو الميل إلى المردان وأوقعت في فاحشة الزنا أو اللواط، أما إذا كان معها آلات لهو موسيقى أو عود أو كمان أو رباب فإنها لا تجوز، حكى غير واحد من أهل العلم الإجماع على ذلك، أما مجرد أغاني بدون آلات لهو فالأكثرون على تحريم ذلك؛ لأنها وسيلة للشر، أما إذا كان باللغة العادية أو باللغة العربية أو باللغة العادية ليس فيها فتنة وكان مضمونها الحق والدعوة إلى الخير وإنكار الباطل فهذه لا بأس بها، كما كان الصحابة ينشدون الأشعار عند النبي ﷺ، ويقرهم بل يأمرهم بهجاء المشركين كما كان يأمر حسان بهجاء المشركين بالأشعار العربية التي تنصر الحق وتهجو الباطل. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8248/حكم-سماع-الشعر-والاغاني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_304/30411.mp3","categories":["الشعر والأغاني"]},{"id":10420,"question":"أسال جزاكم الله خيراً عن حكم قراءة الشعر، وعن حفظه، مع العلم بأني لا أحب الشعر الغزلي وأكرهه؟","title":"حكم قراءة الشعر وحفظه","answer":"الجواب: الشعر شعران، إذا كان في الحكمة والمواعظ والفوائد لا بأس، يقول النبي ﷺ: \"إن من الشعر لحكمة\"، وقد سمع النبي ﷺ شعر حسان وغيره من الصحابة؛ فلا بأس بشرط أن لا يكثر منه وألا يشغله عما هو أهم، أما إذا كان الشعر في الفساد والدعوة إلى الفواحش فهذا لا يجوز، بل هو منكر. وهكذا الأغاني الماجنة أو مع آلات اللهو كله منكر، مع الطنبور مع العود مع الكمان مع الموسيقى لا يجوز، فينبغي للمؤمن التحرز من هذه الأشياء والحذر منها، والله المستعان. نعم.\nالمقدم: الله المستعان، جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8600/حكم-قراءة-الشعر-وحفظه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_317/31708.mp3","categories":["الشعر والأغاني"]},{"id":10774,"question":"يقول أيضاً في آخر سؤال له: معظم مناسبات الزواج والمآتم عندنا مخالفة للسنة، مثلاً في الزواج غناء واختلاط، وفي المآتم جمع بعد الدفن، هل يجوز لي الذهاب للتعزية بدون الجلوس معهم، وفي الزواج إذا دعيت للوليمة ولم يبدأ وقتها ولم يبدأ وقت الحفل ولا الاختلاط هل يجوز لي الذهاب، علماً بأن عدم ذهابي يترتب علي مقاطعات وردود فعل عنيفة منهم؟","title":"حكم حضور الأعراس أو التعزية إذا اشتملت على منكر","answer":"الجواب: إذا استطعت أن تذهب وتعلمهم وتنكر المنكر فهذا هو واجبك، تذهب وتعلم وتنكر المنكر في المآتم وفي الزواجات، وإذا لم تستطع ذلك فلا حرج عليك أن تترك الذهاب إليهم، وإذا قاطعوك فهم الآثمون، أما أنت فقد فعلت ما شرع الله لك من ترك حضور المنكر، لكن لو حضرت لو أنكرت إذا استطعت ذلك تحضر وتنكر المنكر، في المأتم وفي حفل الزواج.\nوالغناء في الزواج إذا كان من النساء لا حرج من النساء فيما بينهن، الأغاني التي يعتادها الناس في الزواج يمدحون الزوج والزوجة وآل الزوج والزوجة ونحو ذلك، بالدف لا بالعود ولا بالطبل ولا بالمزامير ولكن بالدف هذا لا بأس به، وهذا من إعلان النكاح، وكان يفعل في عهد النبي صلى الله عليه وسلم وعهد الصحابة.\nأما إذا كان في الاحتفال اختلاط الرجال بالنساء في الأعراس واستعمال ما حرم الله من المزامير والعود والطبول وأشباه ذلك، فإنك لا تحضر لكن إذا استطعت أن تحضر وتنكر لعلهم يستجيبون لك وجب أن تحضر وتنكر المنكر.\nوهكذا في المآتم إذا كان المأتم من أهل الميت يحيون أياماً وليالي يصنعون طعاماً للناس ويحيون المأتم هذا منكر يعلمون هذا من أمور الجاهلية، يعلمون أن هذا لا يجوز، ولكن يشرع لهم أن يقبلوا الطعام من غيرهم، إذا صنع لهم أقاربهم أو جيرانهم طعاماً يقبلونه، هذا مشروع للجيران والأقارب أن يصنعوا لأهل الميت طعاماً، لأنهم قد شغلوا بميتهم، وقد ثبت عنه ﷺ أنه قال لأهله لما جاء نعي جعفر يوم مؤتة قتل في مؤتة في الشام، أمر أهله أن يصنعوا لأهل جعفر طعاماً قال: اصنعوا لهم طعاماً فإنه قد أتاهم ما يشغلهم فإذا صنع الجيران أو الأقارب طعاماً لأهل الميت ودعوا إليه من يأكل معهم من جيرانهم فلا بأس بذلك، ولا بأس أنهم يصبوا القهوة أو الشاي لمن جاء يعزيهم لا بأس بذلك، لكن يجتمعون على طبول أو أغاني أو ملاهي أو يصنعون طعاماً هم للناس لأجل الميت هذا هو المنكر لا يجوز.\nأما إذا جاءهم ضيف من بعيد وصنعوا طعاماً له ولهم لا بأس بهذا، أو صبوا له القهوة الذي جاء يعزي صبوا له الشاي أو أسقوه شراب لا بأس بذلك هذا من مكارم الأخلاق، أما أن يجتمعوا اجتماعاً خاصاً من أجل الميت على الطبول أو المزامير أو على الذبائح والأكل ونحو ذلك هذا هو الذي من عمل الجاهلية لا يجوز صنعه للميت.\nولكن يصنع الناس لهم يهدون إليهم طعاماً من جيرانهم وأقاربهم لأنهم شغلوا بمصيبة، فالسنة أن يهدى لهم طعاماً من جيرانهم وأقاربهم، وإذا جاءهم الطعام كثير ودعوا إليه من يأكل معهم فلا بأس بذلك ولا حرج في ذلك. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8953/حكم-حضور-الاعراس-او-التعزية-اذا-اشتملت-على-منكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_349/34905.mp3","categories":["الشعر والأغاني"]},{"id":10913,"question":"سؤال آخر -لعله ينبئ عن حياته- سماحة الشيخ يقول: إنه عندما يريد أن ينام، أو يكون في بعض الحالات يتذكر كثيرًا من الأغاني، كيف يتخلص من هذا؟","title":"نصيحة لمن ابتلي بحفظ الأغاني","answer":"الجواب:  هذا أيضًا من أسباب نسيانه، هذا من أسباب نسيانك أيضًا لكتاب ربك، وسنة نبيك، تشاغلك بالأغاني، وتذكرك إياها، وتفكيرك فيها هذا مما ينسيك، وهو من المعاصي التي سمعت أنها من أسباب سوء الحفظ، فاحذرها، وأعرض عنها، ولا تلتفت إليها، وقد عوضك الله عنها خيرًا عظيمًا؛ كتاب ربك، وسنة نبيك -عليه الصلاة والسلام- فالزم كتاب ربك، واحذر الأغاني والمجون. أما الأشعار الطيبة التي فيها الحكمة من أشعار أهل الخير والعلم والصحابة وغيرهم، والأشعار التي تفيدك في دينك وفي لغة القرآن والسنة هذه لا بأس بها إن من الشعر حكمة يقول النبي ﷺ. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9080/نصيحة-لمن-ابتلي-بحفظ-الاغاني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_360/36007.mp3","categories":["نصائح وتوجيهات","الشعر والأغاني"]},{"id":11463,"question":"رسالة من الظهران وبعث بها المستمع سعد القحطاني يسأل ويقول: هل تجوز كتابة شعر الغزل؟ أو هل تجوز قراءته؟ وما هو ميزان العفة في الشرع؟ جزاكم الله خيرًا.","title":"حكم شعر الغزل","answer":"الجواب: كل شعر يدعو إلى الفواحش والمنكر، سمي غزلًا أو غير غزل، أو يدعو إلى شيء من المحرمات؛ لا تجوز كتابته، ولا قراءته على الناس، ولا الاشتغال به؛ لأنه مما يصد عن سبيل الله، ومما يشجع على الفاحشة، ومن لهو الحديث، المنكر الذي ذمه الله، وعابه في قوله سبحانه: وَمِنَ النَّاسِ مَنْ يَشْتَرِي لَهْوَ الْحَدِيثِ لِيُضِلَّ عَنْ سَبِيلِ اللَّهِ بِغَيْرِ عِلْمٍ [لقمان:6]، ذهب أكثر المفسرين إلى أن لهو الحديث هو الغناء المحرم، وما يتبعه من آلات الملاهي -نسأل الله السلامة- نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9644/حكم-شعر-الغزل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_381/38118.mp3","categories":["الشعر والأغاني"]},{"id":11465,"question":"هل يجوز التكسب من الشعر؟","title":"حكم التكسب من الشعر","answer":"الجواب:  إذا كان الشعر مباحًا طيبًا في مصالح المسلمين مؤلف يبيعه ويتكسب به، مثل الشعر في الآداب الشرعية، الشعر في الأحكام، الشعر في الصناعة المباحة، ويبيعه؛ لا بأس، مثلما تباع الكتب المؤلفة، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/9646/حكم-التكسب-من-الشعر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_381/38120.mp3","categories":["الشعر والأغاني"]},{"id":12163,"question":"نعود مع مطلع هذه الحلقة إلى رسالة جمعٍ من الأخوات في ليبيا بعثن برسالة ضمنها عددًا من الأسئلة، عرضنا بعضًا منها في حلقات مضت، وفي هذه الحلقة يسألن ويقلن: نرجو الإفادة حول لباس المرأة المسلمة، وما معنى الجلباب؟ إذ أن هناك بعض النساء في مناسبات الأفراح عندما يدخلن المكان الذي تكون فيه المناسبة يقمن بكشف شعرهن، فهل يجوز هذا، مع العلم بأنه لا يوجد رجال في هذه الأماكن؟ وماذا عن الغناء والرقص في الأفراح بين النساء؟","title":"ضابط لباس المرأة وحكم الغناء والرقص للمرأة","answer":"الجواب:  بسم الله، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فإن استعمال الجلباب أمر مطلوب بين الرجال الأجانب، والجلباب يشبه العباءة، وما أشبهه مما تغطي به المرأة بدنها كله، رأسها وبدنها فوق ثيابها، قال الله تعالى:  يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ وَبَنَاتِكَ وَنِسَاءِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِنْ جَلابِيبِهِنَّ.. [الأحزاب:59] الآية، وفي الصحيح عن أم عطية -رضي الله عنها-: أن النبي ﷺ أمر النساء بحضور العيد، بحضور صلاة العيد، قالت: قال بعض النساء: إن إحدانا ليس لها جلباب، فقال -عليه الصلاة والسلام-: لتلبسها أختها من جلبابها.  فالمقصود: أن الجلباب شيء يستر البدن كله، وهو يشبه العباءة من بعض الوجوه. والواجب على النساء التحجب عن الأجانب، وعدم إظهار شيء من الزينة لهم، كأخي الزوج، وأخي زوج الأخت، وغيرهم ممن ليس محرمًا.  ولا بأس بالغناء المعتاد في العرس بين النساء، وضرب الدف الذي هو الطار، والدف له وجه واحد يضرب في مناسبة العرس لإعلان النكاح وإظهاره، وقد جاءت السنة في ذلك، وكان يستعمل في عهد النبي ﷺ، فلا بأس به لإظهار النكاح وإعلانه في وقت مناسب من الليل من دون سهر. ولا بأس -أيضًا- بالرقص ولا حرج في ذلك بين النساء، ولا بأس بالغناء المعتاد الذي ليس فيه دعوة إلى محرم، ولا تزيين للفواحش، ولكنه مدح للزوج، أو الزوجة، أو أهل الزوج، أو أهل الزوجة، ونحو ذلك مما جرت به العادة. كان النساء يغنين في عهد النبي ﷺ في العرس، ويضربن بالدف، ولا حرج في ذلك، بشرط: أن يكون ذلك ليس فيه اختلاط بين الرجال والنساء، بل يكون خاصًا بالنساء في ليلة العرس لإظهار النكاح وإعلانه، والله ولي التوفيق، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10349/ضابط-لباس-المراة-وحكم-الغناء-والرقص-للمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_442/44201.mp3","categories":["اللباس والزينة","الزفاف ووليمة العرس","الشعر والأغاني"]},{"id":12431,"question":"تقول: ما الحكم في الشعر، والشعر الغزلي، والشعر النبطي خاصة؟ وهل يجوز للمرأة أن تكتب الشعر كمجرد هواية؟ وجهونا جزاكم الله خيرًا.","title":"حكم قول الشعر وسماعه","answer":"الجواب:  الشعر العربي الذي لا بأس به ما فيه محذور، لا بأس به، النبي ﷺ يقول: إن من الشعر حكمة وقد سمع النبي ﷺ شعر حسان، وشعر عبدالله بن أبي أوفى، وشعر عبدالله بن رواحة. المقصود: أنه لا بأس بالشعر الذي ليس فيه محذور، كأن تنشد الشعر في الجود والكرم، في الحث على طاعة الله، في التحذير من المعاصي، في بر الوالدين، في صلة الرحم، في التحريم من المسكرات والمعاصي، سواء رجلًا، أو امرأة، فالأشعار الطيبة لا بأس بها، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10631/حكم-قول-الشعر-وسماعه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_403/40301.mp3","categories":["الشعر والأغاني"]},{"id":12596,"question":"بعض الناس قبل حفل الزوج يحجز شاعرًا، أو شاعرين مقابل مال معين لإحياء حفلة الزواج، ما الحكم في ذلك؟ وما هو توجيهكم للناس؟","title":"حكم الإتيان بالشعراء في حفل الزواج","answer":"الجواب:  الغناء في الزواج بين النساء لا بأس، وضرب الدف وهو الطار، كان في عهد النبي ﷺ وهو من إعلان النكاح، يشرع إعلان النكاح، ومن إعلانه اجتماع النساء، وضرب الدف بينهن بالأغاني العادية التي ليس فيها مدح لمحرم، ولا دعوة إلى محرم، وإنما مدح الزوج والزوجة، أو أسرة الزوج والزوجة، ونحو ذلك، هذا لا حرج فيه في وقت الزفاف ليلة العرس. أما الرجال فليس لهم فعل ذلك، فعل الأغاني والدف أو الطبل ليس لهم ذلك، لكن لو قام بينهم شاعر بالطريقة العربية، والأشعار العربية التي ليس فيها ما حرم الله، من دون دف، ولا طبل، بل أشعار عربية، مثل ينشد لهم أشعارًا جيدة في الجود والكرم في الدعوة إلى الخير، في النهي عن الشر، في مدح الشجاعة، في الجهاد، في أشياء طيبة، فكل هذا لا بأس به، ولو في غير العرس، في أي وقت، كان النبي ﷺ يسمع الشعر الجيد، كان يسمع شعر حسان، وشعر ابن رواحة، وشعر كعب بن مالك، لا بأس بهذا. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10805/حكم-الاتيان-بالشعراء-في-حفل-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_413/41308.mp3","categories":["الشعر والأغاني"]},{"id":14398,"question":"هذه السائلة أم فارس، من أبها، تقول: سماحة الشيخ، هل يجوز للمرأة أن ترقص بين النساء في الأفراح، وإذا كان ذلك على آلة مباحة وكانت المرأة متسترة، أي: غير مبدية لمفاتنها، وهي في مكان لا يراها فيه الرجال؟","title":"حكم رقص المرأة بين النساء","answer":"الجواب: لا أعلم بأسًا في الرقص بين النساء، مع التستر الواجب، لا أعلم بأسًا، إذا كان ما هناك منكر، لا اختلاط، ولا آلات ملاهي، أما الدف فهو مباح للنساء في الأعراس، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12880/حكم-رقص-المراة-بين-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_552/55217.mp3","categories":["الشعر والأغاني","قضايا المرأة"]},{"id":14684,"question":"تقول السائلة في آخر أسئلتها: هل يجوز ضرب الدف قبل يوم الزواج أو بعده؟ علماً بأنني سمعت بأنه لا يضرب إلا في يوم الزفاف فقط.","title":"حكم ضرب الدف للنساء قبل الزواج وبعده","answer":"الجواب: السنة أن يضرب في الزفاف ليلة الزفاف، هذا هو السنة، وهكذا للجواري أيام العيد لا بأس، أما غيره فتركه أحوط، تركه الأحوط للنساء، إنما السنة ضربه بإعلان النكاح ليلة الزفاف، أو كان في يوم العيد، كما فعله بعض الجواري عند النبي ﷺ، وقال لما أنكر عليهن أبو بكر قال: دعهن فإن لكل قوم عيدًا، وهذا عيدنا أهل الإسلام فدل على أنه يسمح للجواري والنساء بضرب الدف يوم العيد، عيد الفطر عيد النحر، وهكذا في الزواج لإعلان النكاح، أما الطبل لا، لا يستمع للطبل، ولكن الدف ذو الوجه الواحد، نعم.","link":"https://binbaz.org.sa/fatwas/13172/حكم-ضرب-الدف-للنساء-قبل-الزواج-وبعده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_560/56011.mp3","categories":["النظر والخلوة والاختلاط","الزفاف ووليمة العرس","الشعر والأغاني"]},{"id":14795,"question":"من أسئلة هذا السائل -سماحة الشيخ- من ليبيا يقول: ما حكم كتابة الشعر والذي هو من نسج الخيال ونسج عقل الإنسان؟ أي: الذي يقوله الإنسان من تلقاء نفسه؟","title":"حكم كتابة الشعر","answer":"الجواب: لا حرج في الشعر، يقول النبي ﷺ: إن من الشعر حكمة إذا كان شعرًا طيبًا في مدح الأخلاق الطيبة، في الحث على الصلاة، في الحث على الأخلاق الفاضلة، في الحث على إحسان عشرة للنساء، في الحث على بر الوالدين، على صلة الرحم إلى غير هذا، إذا كان شعرًا طيبًا، فلا بأس، حسنه حسن، وقبيحه قبيح، إذا كان الشعر في شيء مباح، أو شيء مندوب مطلوب، فهذا طيب، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/13288/حكم-كتابة-الشعر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_561/56118.mp3","categories":["الشعر والأغاني"]},{"id":15794,"question":"إذا غنت المرأة بأغان معينة دون موسيقى فهل يعتبر هذا محرم؟","title":"حكم غناء المرأة بغير موسيقى","answer":"الجواب: الأغاني يجب تركها إذا كانت قد تتعلق بذم ما هو ممدوح، أو مدح ما هو مذموم، أو دعوة إلى الفاحشة، أما إذا كانت الأغاني شيء قليل عارض بيت بيتين، ثم تترك، ولا يترتب عليها شر على أحد، وليس معها موسيقى ولا شيء من آلات الملاهي الأمر سهل، البيت والبيتين. أما إذا كان على سبيل الشعر العربي الأشعار العربية السليمة، فهذا لا بأس بالشعر، يقول النبي ﷺ: إن من الشعر حكمة فإذا كانت أشعارًا عربية باللغة العربية في مدح الحق، وذم الباطل، في الدعوة إلى الخير، فهذا لا بأس به. أما الأغاني التي تهيج الناس إلى الفساد والشر، أو الزنا أو غيرها من المنكرات، فهذه لا تجوز، لكن بيت أو بيتين تقوله المرأة أو يقوله الرجل ليس لقصد الشر، وإنما مر على لسانه عارض، فهذا أمره سهل، وقد بيَّن جمهور أهل العلم أن لهو الحديث هو الغناء، يقول ابن مسعود : \"الغناء ينبت النفاق في القلب كما ينبت الماء البقل\" يريد قوله تعالى: وَمِنَ النَّاسِ مَنْ يَشْتَرِي لَهْوَ الْحَدِيثِ لِيُضِلَّ عَنْ سَبِيلِ اللَّهِ[لقمان:6] فلهو الحديث هو الغناء، فالواجب تركه، والحذر منه، وإذا كان معه آلات لهو موسيقى أو كمان أو عود أو ما يشبه ذلك فهذا التحريم أشد، بل قال بعض أهل العلم: إنه إجماع، حكاه ابن الصلاح، إجماع أهل العلم في التحريم. فالواجب الحذر من ذلك، وعدم التساهل في هذه الأمور إلا إذا كان مثلما تقدم على طريقة الشعر العربي الألفاظ العربية لا بألفاظ الغناء، شعرًا عربيًا فيما ينفع المسلمين في مدح الحق، في ذم الباطل، في الدعوة إلى الخير، والتشجيع عليه، كأشعار المعروفين بالخير، مثل حسان بن ثابت، وكعب بن مالك، وعبدالله بن رواحة، والشعراء بعدهم بالحق، الشعراء الذين يتحرون الحق شعرهم طيب ومقبول، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14379/حكم-غناء-المراة-بغير-موسيقى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_742/nour_74216.mp3","categories":["الشعر والأغاني","قضايا المرأة","الزفاف ووليمة العرس"]},{"id":17858,"question":"من أسئلتها يا سماحة الشيخ حفظكم الله تقول: هل الاستماع إلى الأناشيد الإسلامية فيه شيء؟","title":"حكم سماع الأناشيد الإسلامية","answer":"الجواب: لا ما فيه شيء ليس فيه شيء، إذا كانت الأناشيد سليمة موافقة للشرع ليس فيها منكر فلا بأس. نعم.","link":"https://binbaz.org.sa/fatwas/16864/حكم-سماع-الاناشيد-الاسلامية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_598/59803.mp3","categories":["الشعر والأغاني"]},{"id":18037,"question":"السؤال الثاني: سمعت كلامًا لا أدري أهو حديث أم ماذا: (الغناء زاد الراكب)، بينوا لنا، جزاكم الله خيرًا.","title":"هل القول (الغناء زاد الراكب) حديث؟","answer":"الجواب: ليس بحديث؛ بل هو كلام باطل، والغناء هو رقية الشيطان، وهو في الحقيقة من لهو الحديث الذي نهى الله عنه وحذر منه، وهو مما يصد عن سبيل الله، ومما يشغل القلوب عن التلذذ بقراءة كلام الله وسماع كلام الله . أما الشعر العربي باللغة العربية واللحون العربية، فلا بأس به، إذا كان في مدح الخير وذم الشر، في الدعوة إلى الله، في الترغيب بمكارم الأخلاق ومحاسن الأعمال، والترهيب من مساوئ الأخلاق وسيئ الأعمال، باللحون العربية والشعر العربي لا بلحون الغناء، هذا لا بأس به، كما قال النبي ﷺ: إن من الشعر حكمة يقول عليه الصلاة والسلام: إن من الشعر حكمة، وقد سمع شعر كعب بن زهير وشعر كعب بن مالك وشعر حسان وغيرهم . نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17069/هل-القول-الغناء-زاد-الراكب-حديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_600/60002.mp3","categories":["الشعر والأغاني"]},{"id":18045,"question":"هل يجوز مدح الله  بالشعر بنية القربة ونيل المقصود من الله؟","title":"حكم الثناء على الله بالشعر","answer":"الجواب: نعم، نعم. يمدح بالشعر وبالنثر، كما فعل الصحابة وغيرهم . المقدم: رضي الله تعالى عنهم، جزاكم الله خيرًا. الشيخ: نعم.","link":"https://binbaz.org.sa/fatwas/17078/حكم-الثناء-على-الله-بالشعر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_600/60010.mp3","categories":["الشعر والأغاني"]},{"id":18340,"question":"لقد قيل: إن الأغاني حرام بسبب الموسيقى، فهل هذا صحيح؟ وهل الموسيقى لوحدها حرام أم الشعر الغزل المغنى فيها حرام؟ ويوجد أيضًا بعض الآلات، فهل هي حرام أم لا وهي: الطبل، والربابة، والناي، والمزمار، وآلة البيانو؟","title":"حكم الأغاني والموسيقى","answer":"الجواب: الأغاني محرمة، وقد نص أهل العلم على ذلك، وحكى بعض أهل العلم إجماع أهل العلم على ذلك، ومن أدلة ذلك قوله تعالى: وَمِنَ النَّاسِ مَنْ يَشْتَرِي لَهْوَ الْحَدِيثِ لِيُضِلَّ عَنْ سَبِيلِ اللَّهِ بِغَيْرِ عِلْمٍ [لقمان:6]، قال أكثر علماء التفسير: إن المراد بذلك الأغاني، وهكذا أصوات الملاهي، وقال عليه الصلاة والسلام في الحديث الصحيح: ليكونن من أمتي أقوام يستحلون الحر والحرير والخمر والمعازف، والحر: هو الفرج الحرام يعني: الزنا، والحرير معروف محرم على الرجال، والخمر معروف محرم على الجميع وهو المسكر، والمعازف هي الأغاني وما يعزف به من آلات الملاهي. فالواجب على كل مؤمن ومؤمنة الحذر من ذلك، ولا يجوز استماع ذلك لا من إذاعة ولا من غيرها. أما الشعر العربي الذي ورد في كلام العرب أو في كلام الصحابة وكلام غيرهم، فلا بأس به إذا كان فيه شيء طيب، كالأشعار التي قالها أهل الخير أصحاب النبي ﷺ ومن بعدهم فهذه ليست داخلة في الأغاني، فالشعر بلغة العرب ولحون العرب فيما ينفع الناس كالحث على الاستقامة على الدين، والجود والكرم والعفة والبعد عما حرم الله، هذه أشعار مقبولة كما قال فيها النبي ﷺ: إن من الشعر حكمة، وكان حسان بن ثابت ينشد بحضرة النبي ﷺ وفي المسجد أيضًا يهجو المشركين، ويدعو إلى الإسلام، وهكذا غير حسان كـكعب بن مالك ، وعبد الله بن رواحة وآخرين، وهكذا من بعد الصحابة من أهل العلم. فالمقصود أن الشعر باللغة العربية فيما ينفع الناس هذا ليس فيه بأس وليس من الأغاني، وإنما الأغاني هي ما يكون باللحون المطربة، بلحون الرجال متشبهين بالنساء أو بلحون النساء، هذا هو الذي يضر الناس ويثير الغرائز، ويدعو إلى الفساد ولاسيما إذا كان في مدح النساء أو الخمور أو اللواط.. أو غير هذا مما حرم الله، فيجتمع بذلك الصوت المطرب مع المعنى الفاسد فيكون في هذا شر كثير، وفساد كبير، ولهذا ذكر أهل العلم تحريم ذلك ونص عليه العلماء، وبسط الكلام في ذلك العلامة ابن القيم رحمه الله في كتابه: (إغاثة اللهفان في مكائد الشيطان). فيجب على المسلم والمسلمة الحذر من ذلك وعدم استماعه لا من شريط ولا من إذاعة ولا من تلفاز ولا غير ذلك حفظًا للدين، وحفظًا للمروءة، وحذرًا من أسباب الفتنة والفساد، وإذا كان مع الأغاني آلات الملاهي من الرباب وغيره من أنواع الملاهي كالطبل وكالموسيقى وكالمزمار .. وأشباه ذلك صار الإثم أعظم. وذكر ابن الصلاح وغيره إجماع أهل العلم على تحريم ما يكون فيه اجتماع الغناء مع آلات الملاهي يكون الشر أعظم والفتنة أكبر، وإذا انفرد الغناء وحده ليس معه آلة لهو فالذي عليه جمهور أهل العلم وهو كالإجماع منهم التحريم لما فيه من الفساد، فإذا انضاف إلى ذلك آلات الملاهي من موسيقى أو مزمار أو غير ذلك من آلات الملاهي كالطبل وكالرباب وأشباه ذلك كل ذلك يجعله أشد تحريمًا وأشد فساداً نسأل الله للجميع العافية. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17415/حكم-الاغاني-والموسيقى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_861/nour_86105.mp3","categories":["الشعر والأغاني"]},{"id":18354,"question":"لقد قيل: إن الأغاني حرام بسبب الموسيقى، فهل هذا صحيح؟ وهل الموسيقى لوحدها حرام أم الشعر الغزل المغنى فيها حرام؟ ويوجد أيضًا بعض الآلات، فهل هي حرام أم لا وهي: الطبل، والربابة، والناي، والمزمار، وآلة البيانو؟","title":"حكم الأغاني والموسيقى","answer":"الجواب: الأغاني محرمة، وقد نص أهل العلم على ذلك، وحكى بعض أهل العلم إجماع أهل العلم على ذلك، ومن أدلة ذلك قوله تعالى: وَمِنَ النَّاسِ مَنْ يَشْتَرِي لَهْوَ الْحَدِيثِ لِيُضِلَّ عَنْ سَبِيلِ اللَّهِ بِغَيْرِ عِلْمٍ [لقمان:6]، قال أكثر علماء التفسير: إن المراد بذلك الأغاني، وهكذا أصوات الملاهي، وقال عليه الصلاة والسلام في الحديث الصحيح: ليكونن من أمتي أقوام يستحلون الحر والحرير والخمر والمعازف، والحر: هو الفرج الحرام يعني: الزنا، والحرير معروف محرم على الرجال، والخمر معروف محرم على الجميع وهو المسكر، والمعازف هي الأغاني وما يعزف به من آلات الملاهي. فالواجب على كل مؤمن ومؤمنة الحذر من ذلك، ولا يجوز استماع ذلك لا من إذاعة ولا من غيرها. أما الشعر العربي الذي ورد في كلام العرب أو في كلام الصحابة وكلام غيرهم، فلا بأس به إذا كان فيه شيء طيب، كالأشعار التي قالها أهل الخير أصحاب النبي ﷺ ومن بعدهم فهذه ليست داخلة في الأغاني، فالشعر بلغة العرب ولحون العرب فيما ينفع الناس كالحث على الاستقامة على الدين، والجود والكرم والعفة والبعد عما حرم الله، هذه أشعار مقبولة كما قال فيها النبي ﷺ: إن من الشعر حكمة، وكان حسان بن ثابت ينشد بحضرة النبي ﷺ وفي المسجد أيضًا يهجو المشركين، ويدعو إلى الإسلام، وهكذا غير حسان كـكعب بن مالك ، وعبد الله بن رواحة وآخرين، وهكذا من بعد الصحابة من أهل العلم. فالمقصود أن الشعر باللغة العربية فيما ينفع الناس هذا ليس فيه بأس وليس من الأغاني، وإنما الأغاني هي ما يكون باللحون المطربة، بلحون الرجال متشبهين بالنساء أو بلحون النساء، هذا هو الذي يضر الناس ويثير الغرائز، ويدعو إلى الفساد ولاسيما إذا كان في مدح النساء أو الخمور أو اللواط.. أو غير هذا مما حرم الله، فيجتمع بذلك الصوت المطرب مع المعنى الفاسد فيكون في هذا شر كثير، وفساد كبير، ولهذا ذكر أهل العلم تحريم ذلك ونص عليه العلماء، وبسط الكلام في ذلك العلامة ابن القيم رحمه الله في كتابه: (إغاثة اللهفان في مكائد الشيطان). فيجب على المسلم والمسلمة الحذر من ذلك وعدم استماعه لا من شريط ولا من إذاعة ولا من تلفاز ولا غير ذلك حفظًا للدين، وحفظًا للمروءة، وحذرًا من أسباب الفتنة والفساد، وإذا كان مع الأغاني آلات الملاهي من الرباب وغيره من أنواع الملاهي كالطبل وكالموسيقى وكالمزمار .. وأشباه ذلك صار الإثم أعظم. وذكر ابن الصلاح وغيره إجماع أهل العلم على تحريم ما يكون فيه اجتماع الغناء مع آلات الملاهي يكون الشر أعظم والفتنة أكبر، وإذا انفرد الغناء وحده ليس معه آلة لهو فالذي عليه جمهور أهل العلم وهو كالإجماع منهم التحريم لما فيه من الفساد، فإذا انضاف إلى ذلك آلات الملاهي من موسيقى أو مزمار أو غير ذلك من آلات الملاهي كالطبل وكالرباب وأشباه ذلك كل ذلك يجعله أشد تحريمًا وأشد فساداً نسأل الله للجميع العافية. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17415/حكم-الاغاني-والموسيقى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_861/nour_86105.mp3","categories":["الشعر والأغاني"]},{"id":18410,"question":"يقول السائل من أسئلته يا فضيلة الشيخ! هذا  ما حكم الأناشيد التي تسمى إسلامية ينشدها صبيان وفي بعضها دف؟","title":"حكم الأناشيد التي بها دف","answer":"الجواب: إذا كانت أناشيد سليمة طيبة لا بأس بها، وأما الدف لا، الدف للنساء لا للرجال، الدف للنساء في الأعراس وفي يوم العيد. نعم. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/17490/حكم-الاناشيد-التي-بها-دف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_913/nour_91336.mp3","categories":["الشعر والأغاني"]},{"id":18525,"question":"الأخوات خلود و عهود أحمد عبد الرحمن من جدة، بعثن برسالة، وضمنها عددًا من الأسئلة، يقول السؤال الأول: نحن نعلم أن سماع الأغاني حرام، وبحمد الله نحن لا نستمع إليها، ولكن لدينا جيران يرفعون صوت المذياع ويصل إلينا الصوت، فهل علينا إثم في ذلك؟","title":"حكم سماع الأغاني من غير قصد","answer":"الجواب: ليس عليكم إثم، ليس على من سمع الصوت إثم إذا لم يستمع له ولم يقصده، وإنما مر عليه وسمعه من غير قصد، وإنما الإثم على من فعله أو قصد له واستمع له، وينبغي أن تطالبوا الجيران بخفض أصوات هذه المزامير والأغاني، وليس لهم حق في أن يؤذوكم بذلك، بل الواجب عليهم أن يخفضوا أصوات ما عندهم حتى لا يؤذوا جيرانهم، أما أنتم فليس عليكم حرج إذا لم تستمعوا، وإنما سمعتم فقط من غير قصد، نعم.","link":"https://binbaz.org.sa/fatwas/17626/حكم-سماع-الاغاني-من-غير-قصد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_869/nour_86910.mp3","categories":["الشعر والأغاني"]},{"id":18534,"question":"الأخوات خلود و عهود أحمد عبد الرحمن من جدة، بعثن برسالة، وضمنها عددًا من الأسئلة، يقول السؤال الأول: نحن نعلم أن سماع الأغاني حرام، وبحمد الله نحن لا نستمع إليها، ولكن لدينا جيران يرفعون صوت المذياع ويصل إلينا الصوت، فهل علينا إثم في ذلك؟","title":"حكم سماع الأغاني من غير قصد","answer":"الجواب: ليس عليكم إثم، ليس على من سمع الصوت إثم إذا لم يستمع له ولم يقصده، وإنما مر عليه وسمعه من غير قصد، وإنما الإثم على من فعله أو قصد له واستمع له، وينبغي أن تطالبوا الجيران بخفض أصوات هذه المزامير والأغاني، وليس لهم حق في أن يؤذوكم بذلك، بل الواجب عليهم أن يخفضوا أصوات ما عندهم حتى لا يؤذوا جيرانهم، أما أنتم فليس عليكم حرج إذا لم تستمعوا، وإنما سمعتم فقط من غير قصد، نعم.","link":"https://binbaz.org.sa/fatwas/17626/حكم-سماع-الاغاني-من-غير-قصد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_869/nour_86910.mp3","categories":["الشعر والأغاني"]},{"id":18674,"question":"يسأل أخونا سؤالًا آخر ويقول: ما حكم الإسلام في سماع الأناشيد الدينية الخالية من الآلات الموسيقية؟","title":"حكم سماع الأناشيد الخالية من الآلات الموسيقية","answer":"الجواب: ما نعلم فيها بأس، إذا كانت سليمة ليس فيها إلا كلام طيب، وليس فيها آلات الملاهي فلا بأس بها، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/17840/حكم-سماع-الاناشيد-الخالية-من-الالات-الموسيقية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_873/nour_87314.mp3","categories":["الشعر والأغاني"]},{"id":18676,"question":"يسأل أخونا ويقول: ما حكم القصائد في المدح النبوي خاصة الطريقة المرغنية والضيفية فيما يبدو، وخاصة هذه الطرق لها أنصار ومتفقهون في هذه الناحية، يكادون يتركون القرآن الكريم والسنة المحمدية؟ نرجو نصيحتهم جزاكم الله خيرًا.","title":"حكم القصائد في المدح النبوي","answer":"الجواب: الطرق الصوفية على العموم طرق مبتدعة: مرغنية أو شاذلية أو برهانية أو قادرية أو تيجانية أو غير ذلك، كل هذه الطرق مبتدعة، وبعضها أشد من بعض، كلما كانت الطريقة أكثر مخالفة للشرع؛ صار إثمها أكثر وشرها أعظم، والواجب تركها والاكتفاء بما قاله الله ورسوله، هذا هو الواجب أن يسير المؤمن على طريقة أصحاب النبي ﷺ ومن تبعهم بإحسان في أقواله وأفعاله وحركاته وسكناته، ولا يحدث طريقة جديدة في عباداته، أو في أذكاره، أو غير ذلك، بل يكفيه ما كفى الأولين من أصحاب النبي ﷺ وأتباعهم بإحسان، ولا يجوز لأحد أن يحدث طريقة جديدة يتعبد عليها دون الطريقة التي سار عليها رسول الله ﷺ وأصحابه، وهذه من المصائب العظيمة التي بلي بها الناس. فالواجب على كل مؤمن وعلى كل مؤمنة أن يكتفي بالطريقة التي درج عليها صحابة الرسول ﷺ ودرج عليها أتباعهم بإحسان، وألا يحدث في دين الله ما لم يأذن به الله، قال الله تعالى: أَمْ لَهُمْ شُرَكَاءُ شَرَعُوا لَهُمْ مِنَ الدِّينِ مَا لَمْ يَأْذَنْ بِهِ اللَّهُ [الشورى:21] وقال النبي ﷺ: من أحدث في أمرنا هذا ما ليس منه فهو رد متفق عليه، وقال أيضًا -عليه الصلاة والسلام-: من عمل عملًا ليس عليه أمرنا فهو رد يعني: فهو مردود، فكل الطرق هذا طريقها، إلا طريق النبي ﷺ الذي درج عليه أصحابه  وأرضاهم وأتباعهم بإحسان، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17834/حكم-القصاىد-في-المدح-النبوي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_873/nour_87312.mp3","categories":["الشعر والأغاني"]},{"id":18900,"question":"الأخوات خلود وعهود أحمد عبد الرحمن من جدة، بعثن برسالة، وضمنها عددًا من الأسئلة، يقول السؤال الأول: نحن نعلم أن سماع الأغاني حرام، وبحمد الله نحن لا نستمع إليها، ولكن لدينا جيران يرفعون صوت المذياع، ويصل إلينا الصوت، فهل علينا إثم في ذلك؟","title":"حكم سماع الأغاني من غير قصد","answer":"الجواب: ليس عليكم إثم، ليس على من سمع الصوت إثم إذا لم يستمع له، ولم يقصده، وإنما مر عليه وسمعه من غير قصد، وإنما الإثم على من فعله أو قصد له، واستمع له.  وينبغي أن تطالبوا الجيران بخفض أصوات هذه المزامير والأغاني، وليس لهم حق في أن يؤذوكم بذلك، بل الواجب عليهم أن يخفضوا أصوات ما عندهم؛ حتى لا يؤذوا جيرانهم، أما أنتم فليس عليكم حرج إذا لم تستمعوا، وإنما سمعتم فقط من غير قصد، نعم.","link":"https://binbaz.org.sa/fatwas/18058/حكم-سماع-الاغاني-من-غير-قصد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_881/nour_88109.mp3","categories":["الشعر والأغاني"]}]
